import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AppMode {
  VOICE = 'VOICE',
  IMAGE = 'IMAGE'
}

export interface GermanVoice {
  id: string;
  name: string;
  description: string;
  gender: 'male' | 'female';
  geminiVoice: 'Kore' | 'Puck' | 'Charon' | 'Fenrir' | 'Zephyr';
}

export interface AudioState {
  isPlaying: boolean;
  isLoading: boolean;
  error: string | null;
}

import { GermanVoice } from './types';

export const GERMAN_VOICES: GermanVoice[] = [
  { id: 'v1', name: 'Maximilian', description: 'Tiefe, autoritäre Künstlerstimme', gender: 'male', geminiVoice: 'Kore' },
  { id: 'v2', name: 'Lena', description: 'Sanfte, erzählende Stimme', gender: 'female', geminiVoice: 'Puck' },
  { id: 'v3', name: 'Sebastian', description: 'Klar und professionell', gender: 'male', geminiVoice: 'Charon' },
  { id: 'v4', name: 'Clara', description: 'Energiegeladen und modern', gender: 'female', geminiVoice: 'Zephyr' },
  { id: 'v5', name: 'Erik', description: 'Rau und charakterstark', gender: 'male', geminiVoice: 'Fenrir' },
];

