export function decode(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import { GoogleGenAI, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateSpeech = async (text: string, voiceName: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Sprich auf Deutsch mit hoher Qualität: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Keine Audio-Daten empfangen");
  return base64Audio;
};

export const editImage = async (imageB64: string, prompt: string, mimeType: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: imageB64,
            mimeType: mimeType,
          },
        },
        {
          text: prompt
        },
      ],
    },
  });

  let resultImage: string | null = null;
  for (const part of response.candidates?.[0]?.content?.parts || []) {
    if (part.inlineData) {
      resultImage = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      break;
    }
  }

  if (!resultImage) {
    throw new Error("Bildbearbeitung fehlgeschlagen");
  }

  return resultImage;
};

import React, { useState, useRef } from 'react';
import { GERMAN_VOICES, SAMPLE_TEXTS } from '../constants';
import { generateSpeech } from '../services/gemini';
import { decode, decodeAudioData } from '../utils/audio';

export const VoiceStudio: React.FC = () => {
  const [text, setText] = useState('');
  const [selectedVoice, setSelectedVoice] = useState(GERMAN_VOICES[0]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const handleGenerate = async () => {
    if (!text.trim()) return;

    setIsLoading(true);
    setError(null);
    try {
      const base64 = await generateSpeech(text, selectedVoice.geminiVoice);

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.start();
    } catch (err: any) {
      setError(err.message || 'Ein Fehler ist aufgetreten.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="bg-slate-800/50 p-6 rounded-2xl border border-slate-700 shadow-xl">
        <label className="block text-sm font-medium text-slate-400 mb-2">Deutscher Text</label>
        <textarea
          className="w-full bg-slate-900 border border-slate-700 rounded-xl p-4 text-white focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all h-40 resize-none"
          placeholder="Geben Sie hier Ihren deutschen Text ein..."
          value={text}
          onChange={(e) => setText(e.target.value)}
        />
        <div className="mt-3 flex flex-wrap gap-2">
          {SAMPLE_TEXTS.map((t, idx) => (
            <button
              key={idx}
              onClick={() => setText(t)}
              className="text-xs bg-slate-700 hover:bg-slate-600 px-3 py-1 rounded-full transition-colors"
            >
              Beispiel {idx + 1}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {GERMAN_VOICES.map((voice) => (
          <button
            key={voice.id}
            onClick={() => setSelectedVoice(voice)}
            className={`p-4 rounded-xl border transition-all text-left ${
              selectedVoice.id === voice.id 
                ? 'bg-indigo-600/20 border-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.2)]' 
                : 'bg-slate-800 border-slate-700 hover:bg-slate-750'
            }`}
          >
            <div className="font-bold text-white">{voice.name}</div>
            <div className="text-xs text-slate-400 mt-1">{voice.description}</div>
            <div className={`text-[10px] mt-2 inline-block px-2 py-0.5 rounded uppercase font-bold ${voice.gender === 'male' ? 'bg-blue-500/20 text-blue-400' : 'bg-pink-500/20 text-pink-400'}`}>
              {voice.gender === 'male' ? 'Männlich' : 'Weiblich'}
            </div>
          </button>
        ))}
      </div>

      <button
        onClick={handleGenerate}
        disabled={isLoading || !text.trim()}
        className={`w-full py-4 rounded-xl font-bold text-lg shadow-lg transition-all flex items-center justify-center space-x-2 ${
          isLoading || !text.trim()
            ? 'bg-slate-700 text-slate-500 cursor-not-allowed'
            : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white transform hover:-translate-y-1'
        }`}
      >
        {isLoading ? (
          <>
            <div className="animate-spin rounded-full h-5 w-5 border-2 border-white/20 border-t-white"></div>
            <span>Generiere Stimme...</span>
          </>
        ) : (
          <>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <span>In Audio umwandeln</span>
          </>
        )}
      </button>

      {error && (
        <div className="bg-red-500/10 border border-red-500/50 text-red-400 p-4 rounded-xl text-center">
          {error}
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { SAMPLE_IMAGE_PROMPTS } from '../constants';
import { editImage } from '../services/gemini';

export const ImageStudio: React.FC = () => {
  const [image, setImage] = useState<string | null>(null);
  const [mimeType, setMimeType] = useState('');
  const [prompt, setPrompt] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [history, setHistory] = useState<string[]>([]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const result = event.target?.result as string;
        const b64 = result.split(',')[1];
        setImage(b64);
        setMimeType(file.type);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleEdit = async () => {
    if (!image || !prompt.trim()) return;

    setIsProcessing(true);
    setError(null);
    try {
      const result = await editImage(image, prompt, mimeType);
      const b64 = result.split(',')[1];
      setImage(b64);
      setHistory(prev => [result, ...prev].slice(0, 5));
      setPrompt('');
    } catch (err: any) {
      setError(err.message || 'Bildbearbeitung fehlgeschlagen.');
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-4">
          <div className="bg-slate-800/50 p-4 rounded-2xl border border-slate-700 min-h-[400px] flex flex-col items-center justify-center relative overflow-hidden group">
            {image ? (
              <>
                <img 
                  src={`data:${mimeType};base64,${image}`} 
                  alt="Original" 
                  className="max-h-[500px] w-auto rounded-lg shadow-2xl transition-transform group-hover:scale-[1.02]" 
                />
                <button 
                  onClick={() => setImage(null)}
                  className="absolute top-4 right-4 bg-red-500/80 hover:bg-red-600 p-2 rounded-full text-white shadow-lg backdrop-blur-sm"
                >
                  <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </>
            ) : (
              <div className="text-center p-12 border-2 border-dashed border-slate-600 rounded-xl w-full">
                <svg className="mx-auto h-12 w-12 text-slate-500 mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                </svg>
                <input 
                  type="file" 
                  id="image-upload" 
                  className="hidden" 
                  accept="image/*"
                  onChange={handleFileChange}
                />
                <label 
                  htmlFor="image-upload"
                  className="bg-indigo-600 hover:bg-indigo-500 px-6 py-3 rounded-xl font-bold text-white cursor-pointer transition-colors inline-block"
                >
                  Bild auswählen
                </label>
                <p className="mt-4 text-slate-400 text-sm">Unterstützt JPG, PNG, WEBP</p>
              </div>
            )}
          </div>

          {history.length > 0 && (
            <div className="bg-slate-800/30 p-4 rounded-xl">
              <h3 className="text-sm font-semibold text-slate-400 mb-3">Verlauf</h3>
              <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                {history.map((h, i) => (
                  <img 
                    key={i} 
                    src={h} 
                    alt={`Verlauf ${i}`} 
                    className="h-20 w-20 object-cover rounded-lg border border-slate-600 cursor-pointer hover:border-indigo-500"
                    onClick={() => {
                      const b64 = h.split(',')[1];
                      setImage(b64);
                    }}
                  />
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="bg-slate-800/50 p-6 rounded-2xl border border-slate-700 shadow-xl">
            <h3 className="text-lg font-bold text-white mb-4">Bearbeitungsbefehl</h3>
            <div className="space-y-4">
              <textarea
                className="w-full bg-slate-900 border border-slate-700 rounded-xl p-4 text-white focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all h-32 resize-none"
                placeholder="Was möchten Sie ändern? (z.B. 'Füge einen Hund im Hintergrund hinzu' oder 'Mache es schwarz-weiß')"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
              />
              <div className="flex flex-wrap gap-2">
                {SAMPLE_IMAGE_PROMPTS.map((p, idx) => (
                  <button
                    key={idx}
                    onClick={() => setPrompt(p)}
                    className="text-xs bg-slate-700 hover:bg-slate-600 px-3 py-1 rounded-full text-slate-300 transition-colors"
                  >
                    {p}
                  </button>
                ))}
              </div>
              <button
                onClick={handleEdit}
                disabled={isProcessing || !image || !prompt.trim()}
                className={`w-full py-4 rounded-xl font-bold text-lg shadow-lg transition-all flex items-center justify-center space-x-2 ${
                  isProcessing || !image || !prompt.trim()
                    ? 'bg-slate-700 text-slate-500 cursor-not-allowed'
                    : 'bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white transform hover:-translate-y-1'
                }`}
              >
                {isProcessing ? (
                  <>
                    <div className="animate-spin rounded-full h-5 w-5 border-2 border-white/20 border-t-white"></div>
                    <span>Bearbeite Bild...</span>
                  </>
                ) : (
                  <>
                    <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                    </svg>
                    <span>Änderungen anwenden</span>
                  </>
                )}
              </button>
            </div>
          </div>

          <div className="bg-indigo-900/20 border border-indigo-500/30 p-6 rounded-2xl">
            <h4 className="font-semibold text-indigo-400 mb-2 flex items-center">
              <svg className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              Tipp zur Nano Banana Engine
            </h4>
            <p className="text-slate-400 text-sm leading-relaxed">
              Die Gemini 2.5 Flash Image Engine versteht natürliche Sprache hervorragend. 
              Sie können komplexe Anweisungen geben wie "Platziere das Objekt in einer futuristischen Stadt zur blauen Stunde".
            </p>
          </div>
        </div>
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/50 text-red-400 p-4 rounded-xl text-center">
          {error}
        </div>
      )}
    </div>
  );
};

