// Fix: Add missing editImage function following the @google/genai SDK guidelines
export const editImage = async (base64Image: string, prompt: string, mimeType: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-image',
    contents: {
      parts: [
        {
          inlineData: {
            data: base64Image,
            mimeType: mimeType,
          },
        },
        {
          text: prompt,
        },
      ],
    },
  });

  // Iterate through parts to find the image response as per SDK documentation
  if (response.candidates && response.candidates[0].content.parts) {
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        const base64EncodeString: string = part.inlineData.data;
        // Return as data URL to be compatible with typical img src and the split logic in ImageStudio
        return `data:${part.inlineData.mimeType};base64,${base64EncodeString}`;
      }
    }
  }

  throw new Error("Bildbearbeitung fehlgeschlagen: Kein Bild im Ergebnis gefunden.");
};

