import React, { useState, useRef, useEffect } from 'react';
import { GERMAN_VOICES, SAMPLE_TEXTS } from '../constants';
import { generateSpeech } from '../services/gemini';
import { decode, decodeAudioData } from '../utils/audio';

export const VoiceStudio: React.FC = () => {
  const [text, setText] = useState('');
  const [selectedVoice, setSelectedVoice] = useState(GERMAN_VOICES[0]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    };
  }, []);

  const stopAudio = () => {
    if (sourceNodeRef.current) {
      try {
        sourceNodeRef.current.stop();
      } catch (e) {
        // Source might have already stopped
      }
      sourceNodeRef.current = null;
    }
    setIsPlaying(false);
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;

    setIsLoading(true);
    setError(null);
    stopAudio();

    try {
      const base64 = await generateSpeech(text, selectedVoice.geminiVoice);

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = () => setIsPlaying(false);

      sourceNodeRef.current = source;
      source.start();
      setIsPlaying(true);
    } catch (err: any) {
      setError(err.message || 'Ein Fehler ist bei der Audiogenerierung aufgetreten.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      {/* Input Section */}
      <div className="bg-slate-800/40 backdrop-blur-xl p-8 rounded-3xl border border-white/10 shadow-2xl">
        <div className="flex justify-between items-center mb-4">
          <label className="text-sm font-semibold text-indigo-300 uppercase tracking-wider">Künstlerisches Manuskript</label>
          <button 
            onClick={() => { navigator.clipboard.writeText(text); }}
            className="text-xs text-slate-500 hover:text-white transition-colors flex items-center gap-1"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" /></svg>
            Kopieren
          </button>
        </div>
        <textarea
          className="w-full bg-slate-900/50 border border-slate-700/50 rounded-2xl p-6 text-white text-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all h-52 resize-none placeholder-slate-600 shadow-inner"
          placeholder="Schreiben Sie hier Ihren Text für die Vertonung..."
          value={text}
          onChange={(e) => setText(e.target.value)}
        />
        <div className="mt-4 flex flex-wrap gap-2">
          {SAMPLE_TEXTS.map((t, idx) => (
            <button
              key={idx}
              onClick={() => setText(t)}
              className="text-[11px] font-medium bg-slate-700/40 hover:bg-slate-600/60 px-4 py-2 rounded-full border border-white/5 text-slate-300 transition-all hover:scale-105 active:scale-95"
            >
              Inspiration {idx + 1}
            </button>
          ))}
        </div>
      </div>

      {/* Voice Selection Section */}
      <div>
        <h3 className="text-sm font-semibold text-indigo-300 uppercase tracking-wider mb-4 px-2">Wählen Sie einen Sprecher</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {GERMAN_VOICES.map((voice) => (
            <button
              key={voice.id}
              onClick={() => setSelectedVoice(voice)}
              className={`group p-6 rounded-2xl border transition-all text-left relative overflow-hidden ${
                selectedVoice.id === voice.id 
                  ? 'bg-indigo-600/20 border-indigo-500/50 shadow-[0_0_30px_rgba(99,102,241,0.15)]' 
                  : 'bg-slate-800/40 border-slate-700/50 hover:bg-slate-750/60'
              }`}
            >
              <div className="relative z-10">
                <div className="flex justify-between items-start mb-2">
                  <span className="font-bold text-white text-lg group-hover:text-indigo-200 transition-colors">{voice.name}</span>
                  <div className={`text-[9px] px-2 py-0.5 rounded-full uppercase font-black tracking-tighter ${voice.gender === 'male' ? 'bg-blue-500/20 text-blue-400' : 'bg-pink-500/20 text-pink-400'}`}>
                    {voice.gender === 'male' ? 'Männlich' : 'Weiblich'}
                  </div>
                </div>
                <p className="text-xs text-slate-400 leading-relaxed h-8 line-clamp-2">{voice.description}</p>
              </div>
              {selectedVoice.id === voice.id && (
                <div className="absolute bottom-0 right-0 w-16 h-16 bg-indigo-500/10 blur-2xl rounded-full -mr-8 -mb-8"></div>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* Action Section */}
      <div className="flex gap-4">
        <button
          onClick={handleGenerate}
          disabled={isLoading || !text.trim()}
          className={`flex-1 py-5 rounded-2xl font-black text-xl shadow-2xl transition-all flex items-center justify-center space-x-3 group relative overflow-hidden ${
            isLoading || !text.trim()
              ? 'bg-slate-700/50 text-slate-500 cursor-not-allowed border border-slate-600/50'
              : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 text-white transform hover:-translate-y-1 active:scale-[0.98]'
          }`}
        >
          {isLoading ? (
            <>
              <div className="animate-spin rounded-full h-6 w-6 border-3 border-white/20 border-t-white"></div>
              <span className="tracking-tight">Verarbeite Kunstwerk...</span>
            </>
          ) : (
            <>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-7 w-7 transition-transform group-hover:scale-110" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
              </svg>
              <span className="tracking-tight">STIMME GENERIEREN</span>
            </>
          )}
        </button>

        {isPlaying && (
          <button
            onClick={stopAudio}
            className="px-8 bg-red-500/20 hover:bg-red-500/30 border border-red-500/50 text-red-400 rounded-2xl transition-all flex items-center gap-2 group"
          >
            <div className="w-3 h-3 bg-red-400 rounded-sm animate-pulse"></div>
            <span className="font-bold text-sm tracking-widest uppercase">Stop</span>
          </button>
        )}
      </div>

      {error && (
        <div className="bg-red-500/10 border border-red-500/30 text-red-400 p-6 rounded-2xl text-center animate-shake flex items-center justify-center gap-3">
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          <span className="font-medium">{error}</span>
        </div>
      )}
    </div>
  );
};

