                {words.map((part, idx) => {
                  const isWhitespace = /^\s+$/.test(part);
                  // We need to map the full parts list back to our timing list which only has words
                  const wordList = words.filter(w => !/^\s+$/.test(w));
                  const wordOnlyIndex = wordList.indexOf(part);
                  const isSpoken = !isWhitespace && wordOnlyIndex === currentWordIndex;

                  return (
                    <span 
                      key={idx} 
                      className={`transition-all duration-300 ${
                        isSpoken 
                          ? 'text-indigo-400 font-normal drop-shadow-[0_0_12px_rgba(129,140,248,0.8)] scale-110 inline-block' 
