            ) : (
              <div className="flex items-center gap-4">
                <svg className="w-8 h-8 text-white fill-white transition-transform group-hover:scale-110" viewBox="0 0 24 24">
                   <path d="M8 5v14l11-7z" />
                </svg>
                <span className="font-black text-white text-xl tracking-[0.2em] uppercase">Klang erschaffen</span>
              </div>
