          {isPlaying && (
            <button
              onClick={stopAudio}
              className="px-8 rounded-3xl border border-red-500/30 bg-red-500/5 text-red-400 font-black tracking-widest uppercase hover:bg-red-500 hover:text-white transition-all animate-pulse flex items-center justify-center"
