import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GERMAN_VOICES, SAMPLE_TEXTS } from '../constants';
import { generateSpeech } from '../services/gemini';
import { decode, decodeAudioData, createWavBlob } from '../utils/audio';

interface WordTiming {
  word: string;
  start: number;
  end: number;
}

export const VoiceStudio: React.FC = () => {
  const [text, setText] = useState('');
  const [selectedVoice, setSelectedVoice] = useState(GERMAN_VOICES[0]);
  const [isLoading, setIsLoading] = useState(false);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [lastAudioBase64, setLastAudioBase64] = useState<string | null>(null);
  const [currentWordIndex, setCurrentWordIndex] = useState(-1);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const previewSourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const startTimeRef = useRef<number>(0);
  const wordTimingsRef = useRef<WordTiming[]>([]);
  const animationFrameRef = useRef<number>(0);

  useEffect(() => {
    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
      cancelAnimationFrame(animationFrameRef.current);
    };
  }, []);

  const words = useMemo(() => {
    return text.split(/(\s+)/).filter(Boolean);
  }, [text]);

  const stopAllAudio = () => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); } catch (e) {}
      sourceNodeRef.current = null;
    }
    if (previewSourceNodeRef.current) {
      try { previewSourceNodeRef.current.stop(); } catch (e) {}
      previewSourceNodeRef.current = null;
    }
    setIsPlaying(false);
    setPreviewingVoiceId(null);
    setCurrentWordIndex(-1);
    cancelAnimationFrame(animationFrameRef.current);
  };

  const handlePreview = async (e: React.MouseEvent, voice: typeof GERMAN_VOICES[0]) => {
    e.stopPropagation();
    if (previewingVoiceId === voice.id) {
      stopAllAudio();
      return;
    }

    stopAllAudio();
    setPreviewingVoiceId(voice.id);

    try {
      const base64 = await generateSpeech(voice.previewSnippet, voice.geminiVoice);

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);

      previewSourceNodeRef.current = source;
      source.start();
      source.onended = () => setPreviewingVoiceId(null);
    } catch (err: any) {
      setError("Preview konnte nicht geladen werden.");
      setPreviewingVoiceId(null);
    }
  };

  const updateHighlight = () => {
    if (!audioContextRef.current || !isPlaying) return;

    const elapsed = audioContextRef.current.currentTime - startTimeRef.current;
    const timings = wordTimingsRef.current;

    let foundIndex = -1;
    for (let i = 0; i < timings.length; i++) {
      if (elapsed >= timings[i].start && elapsed <= timings[i].end) {
        foundIndex = i;
        break;
      }
    }

    if (foundIndex !== currentWordIndex) {
      setCurrentWordIndex(foundIndex);
    }

    if (elapsed < timings[timings.length - 1]?.end) {
      animationFrameRef.current = requestAnimationFrame(updateHighlight);
    } else {
      setIsPlaying(false);
      setCurrentWordIndex(-1);
    }
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;

    setIsLoading(true);
    setError(null);
    setLastAudioBase64(null);
    stopAllAudio();

    try {
      const base64 = await generateSpeech(text, selectedVoice.geminiVoice);
      setLastAudioBase64(base64);

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const duration = audioBuffer.duration;

      const textWords = words.filter(w => !/^\s+$/.test(w));
      const totalChars = textWords.join('').length;
      let currentOffset = 0;

      wordTimingsRef.current = textWords.map(word => {
        const wordWeight = word.length / totalChars;
        const wordDuration = wordWeight * duration;
        const timing = { word, start: currentOffset, end: currentOffset + wordDuration };
        currentOffset += wordDuration;
        return timing;
      });

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);

      sourceNodeRef.current = source;
      startTimeRef.current = ctx.currentTime;
      source.start();
      setIsPlaying(true);
      animationFrameRef.current = requestAnimationFrame(updateHighlight);

      source.onended = () => {
        setIsPlaying(false);
        setCurrentWordIndex(-1);
      };
    } catch (err: any) {
      setError(err.message || 'Ein Fehler ist aufgetreten.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDownload = () => {
    if (!lastAudioBase64) return;
    const pcmData = decode(lastAudioBase64);
    const blob = createWavBlob(pcmData, 24000);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Deutsch-KI_${selectedVoice.name.replace(/\s+/g, '_')}_320kbps.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-12 animate-fadeIn max-w-5xl mx-auto">
      {/* Manuscript Area */}
      <section className="relative group">
        <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-[2rem] blur opacity-25 group-hover:opacity-40 transition duration-1000 group-hover:duration-200"></div>
        <div className="relative bg-slate-900/80 backdrop-blur-2xl p-8 rounded-[2rem] border border-white/10 shadow-2xl overflow-hidden min-h-[320px]">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-sm font-black text-indigo-400 uppercase tracking-[0.2em]">Künstlerisches Manuskript</h3>
            <div className="flex gap-4">
               {SAMPLE_TEXTS.map((_, idx) => (
                <button
                  key={idx}
                  onClick={() => setText(SAMPLE_TEXTS[idx])}
                  className="w-8 h-8 flex items-center justify-center rounded-full bg-slate-800 border border-white/5 text-xs text-slate-400 hover:bg-indigo-600 hover:text-white transition-all shadow-lg"
                  title={`Beispiel ${idx + 1}`}
                >
                  {idx + 1}
                </button>
              ))}
            </div>
          </div>

          <div className="relative w-full h-48">
            {isPlaying && (
              <div className="absolute inset-0 z-10 text-white text-2xl font-light leading-relaxed pointer-events-none overflow-y-auto whitespace-pre-wrap">
                {words.map((part, idx) => {
                  const isWhitespace = /^\s+$/.test(part);
                  const wordList = words.filter(w => !/^\s+$/.test(w));
                  const wordOnlyIndex = wordList.indexOf(part);
                  const isSpoken = !isWhitespace && wordOnlyIndex === currentWordIndex;
                  return (
                    <span key={idx} className={`transition-all duration-300 ${isSpoken ? 'text-indigo-400 font-normal drop-shadow-[0_0_12px_rgba(129,140,248,0.8)] scale-110 inline-block' : 'opacity-40'}`}>
                      {part}
                    </span>
                  );
                })}
              </div>
            )}
            <textarea
              className={`w-full bg-transparent border-none focus:ring-0 p-0 text-white text-2xl font-light placeholder-slate-700 h-full resize-none leading-relaxed transition-opacity duration-500 ${isPlaying ? 'opacity-0' : 'opacity-100'}`}
              placeholder="Schreiben Sie hier Ihre Vision..."
              value={text}
              onChange={(e) => setText(e.target.value)}
              disabled={isPlaying}
            />
          </div>

          <div className="mt-6 flex items-center justify-between border-t border-white/5 pt-6">
            <div className="flex items-center gap-2 text-slate-500 text-xs font-mono">
              <span className={`w-2 h-2 rounded-full transition-all duration-500 ${isPlaying ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.8)]' : 'bg-indigo-500 shadow-[0_0_8px_rgba(99,102,241,0.6)]'}`}></span>
              {isPlaying ? 'WIEDERGABE LÄUFT...' : `${text.length} ZEICHEN`}
            </div>
            <button onClick={() => { stopAllAudio(); setText(''); }} className="text-slate-600 hover:text-red-400 transition-colors text-xs uppercase font-bold tracking-widest">Leeren</button>
          </div>
        </div>
      </section>

      {/* Voice Selection */}
      <section>
        <div className="flex items-baseline justify-between mb-8 px-4">
          <h3 className="text-xl font-bold text-white tracking-tight">Künstler Ensemble</h3>
          <span className="text-xs text-slate-500 font-mono opacity-60">PERSONA & TEST</span>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {GERMAN_VOICES.map((voice) => (
            <button
              key={voice.id}
              onClick={() => setSelectedVoice(voice)}
              className={`relative p-6 rounded-2xl border transition-all duration-500 text-left group overflow-hidden ${
                selectedVoice.id === voice.id 
                  ? 'bg-white/10 border-indigo-500/60 shadow-[0_0_40px_rgba(99,102,241,0.15)]' 
                  : 'bg-slate-900/40 border-slate-800/50 hover:border-slate-600 hover:bg-white/5'
              }`}
            >
              <div className="relative z-10">
                <div className="flex justify-between items-start mb-3">
                  <div className={`text-[9px] font-black uppercase tracking-widest ${voice.gender === 'male' ? 'text-cyan-400' : 'text-pink-400'}`}>
                    {voice.persona}
                  </div>
                  <button 
                    onClick={(e) => handlePreview(e, voice)}
                    className={`p-2 rounded-full border transition-all ${
                      previewingVoiceId === voice.id 
                        ? 'bg-indigo-500 border-indigo-400 text-white animate-pulse' 
                        : 'bg-slate-800/80 border-white/10 text-slate-400 hover:text-white hover:border-white/30'
                    }`}
                  >
                    {previewingVoiceId === voice.id ? (
                      <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
                    ) : (
                      <svg className="w-3 h-3 translate-x-0.5" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                    )}
                  </button>
                </div>
                <h4 className={`font-bold text-lg mb-1 transition-colors ${selectedVoice.id === voice.id ? 'text-white' : 'text-slate-300'}`}>
                  {voice.name}
                </h4>
                <p className="text-[11px] text-slate-500 leading-relaxed line-clamp-2 italic italic">
                  {voice.description}
                </p>
              </div>
              {selectedVoice.id === voice.id && (
                <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/10 to-purple-500/10 pointer-events-none"></div>
              )}
            </button>
          ))}
        </div>
      </section>

      {/* Actions */}
      <div className="flex flex-col sm:flex-row gap-4 pt-6">
        <button
          onClick={handleGenerate}
          disabled={isLoading || !text.trim()}
          className={`relative flex-[2] group overflow-hidden rounded-3xl p-px transition-all duration-500 ${isLoading || !text.trim() ? 'opacity-50 grayscale' : 'hover:scale-[1.01] active:scale-[0.99]'}`}
        >
          <div className="absolute inset-0 bg-gradient-to-r from-indigo-600 via-purple-600 to-indigo-600 animate-gradient-x"></div>
          <div className="relative bg-slate-950 rounded-[calc(1.5rem-1px)] py-6 flex items-center justify-center gap-4 transition-colors group-hover:bg-transparent">
            {isLoading ? (
              <div className="flex items-center gap-3">
                <div className="w-5 h-5 border-2 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
                <span className="font-black text-white tracking-[0.3em] uppercase">Generiere Frequenz...</span>
              </div>
            ) : (
              <div className="flex items-center gap-4">
                <svg className="w-8 h-8 text-white fill-white transition-transform group-hover:scale-110" viewBox="0 0 24 24"><path d="M8 5v14l11-7z" /></svg>
                <span className="font-black text-white text-xl tracking-[0.2em] uppercase">Klang erschaffen</span>
              </div>
            )}
          </div>
        </button>

        <div className="flex flex-1 gap-4">
          {lastAudioBase64 && (
            <button
              onClick={handleDownload}
              className="flex-1 px-6 rounded-3xl border border-white/10 bg-white/5 hover:bg-white/10 text-white font-black tracking-widest uppercase transition-all flex items-center justify-center gap-3 group relative overflow-hidden"
            >
              <div className="absolute inset-0 bg-indigo-500/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
              <svg className="w-5 h-5 relative z-10 group-hover:translate-y-0.5 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              <span className="relative z-10 text-sm">Download</span>
            </button>
          )}
          {isPlaying && (
            <button onClick={stopAllAudio} className="px-8 rounded-3xl border border-red-500/30 bg-red-500/5 text-red-400 font-black tracking-widest uppercase hover:bg-red-500 hover:text-white transition-all animate-pulse flex items-center justify-center">Stop</button>
          )}
        </div>
      </div>
      {error && <div className="bg-red-950/20 border border-red-500/30 p-6 rounded-2xl text-center text-red-400 text-sm font-medium backdrop-blur-md animate-shake">{error}</div>}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GERMAN_VOICES, SAMPLE_TEXTS } from '../constants';
import { generateSpeech } from '../services/gemini';
import { decode, decodeAudioData, createWavBlob } from '../utils/audio';

interface WordTiming {
  word: string;
  start: number;
  end: number;
}

export const VoiceStudio: React.FC = () => {
  const [text, setText] = useState('');
  const [selectedVoice, setSelectedVoice] = useState(GERMAN_VOICES[0]);
  const [isLoading, setIsLoading] = useState(false);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [lastAudioBase64, setLastAudioBase64] = useState<string | null>(null);
  const [currentWordIndex, setCurrentWordIndex] = useState(-1);
  const [favorites, setFavorites] = useState<string[]>(() => {
    const saved = localStorage.getItem('deutsch-ki-favorites');
    return saved ? JSON.parse(saved) : [];
  });

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const previewSourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const startTimeRef = useRef<number>(0);
  const wordTimingsRef = useRef<WordTiming[]>([]);
  const animationFrameRef = useRef<number>(0);

  useEffect(() => {
    localStorage.setItem('deutsch-ki-favorites', JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
      cancelAnimationFrame(animationFrameRef.current);
    };
  }, []);

  const words = useMemo(() => {
    return text.split(/(\s+)/).filter(Boolean);
  }, [text]);

  const favoriteVoices = useMemo(() => {
    return GERMAN_VOICES.filter(v => favorites.includes(v.id));
