        </div>
      </div>

      {error && (
        <div className="bg-red-950/20 border border-red-500/30 p-8 rounded-3xl text-center text-red-400 text-sm font-black tracking-widest uppercase backdrop-blur-xl animate-shake">
          {error}
        </div>
      )}
    </div>
  );
};

{
  "name": "Deutsch-KI Super App",
  "description": "Eine erstklassige Anwendung zur Konvertierung von deutschem Text in hochwertige Sprache mit Gemini 2.5 Flash.",
  "requestFramePermissions": [
    "camera"
  ]
}

import { GoogleGenAI, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates high-quality German speech from text.
 */
export const generateSpeech = async (text: string, voiceName: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Bitte sprich diesen deutschen Text mit maximaler künstlerischer Qualität, klarer Artikulation und emotionalem Ausdruck: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audiogenerierung fehlgeschlagen. Keine Daten empfangen.");
  return base64Audio;
};

/**
 * Extracts German text from an image (OCR).
 */
export const extractTextFromImage = async (base64Image: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: base64Image } },
        { text: "Extrahiere den gesamten deutschen Text aus diesem Bild. Gib nur den extrahierten Text zurück, ohne Kommentare." }
      ]
    }
  });

  return response.text || "";
};

import React, { useRef, useState, useEffect } from 'react';
import { extractTextFromImage } from '../services/gemini';

interface CameraScannerProps {
  onTextScanned: (text: string) => void;
  onClose: () => void;
}

export const CameraScanner: React.FC<CameraScannerProps> = ({ onTextScanned, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let stream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment' }, 
          audio: false 
        });
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        setError("Kamera konnte nicht gestartet werden. Bitte überprüfen Sie die Berechtigungen.");
      }
    };

    startCamera();

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  const captureAndScan = async () => {
    if (!videoRef.current || !canvasRef.current) return;

    setIsScanning(true);
    setError(null);

    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (ctx) {
      ctx.drawImage(video, 0, 0);
      const base64 = canvas.toDataURL('image/jpeg').split(',')[1];

      try {
        const text = await extractTextFromImage(base64);
        if (text.trim()) {
          onTextScanned(text);
          onClose();
        } else {
          setError("Kein Text im Bild gefunden.");
        }
      } catch (err) {
        setError("Fehler bei der Texterkennung.");
      } finally {
        setIsScanning(false);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-black/95 backdrop-blur-xl flex flex-col items-center justify-center p-6 animate-fadeIn">
      <div className="relative w-full max-w-2xl aspect-[3/4] rounded-3xl overflow-hidden border border-white/10 shadow-2xl">
        <video 
          ref={videoRef} 
          autoPlay 
          playsInline 
          className="w-full h-full object-cover"
        />
        <canvas ref={canvasRef} className="hidden" />

        {/* Overlay scanning effect */}
        {isScanning && (
          <div className="absolute inset-0 bg-indigo-500/20 animate-pulse flex items-center justify-center">
            <div className="w-full h-1 bg-indigo-400 shadow-[0_0_20px_rgba(129,140,248,0.8)] animate-scanLine"></div>
          </div>
        )}

        <div className="absolute inset-0 border-2 border-dashed border-white/20 rounded-3xl m-8 pointer-events-none"></div>
      </div>

      <div className="mt-8 flex flex-col items-center gap-6 w-full max-w-md">
        {error && (
          <div className="text-red-400 text-xs font-black uppercase tracking-widest text-center animate-shake">
            {error}
          </div>
        )}

        <div className="flex items-center gap-8">
          <button 
            onClick={onClose}
            className="w-16 h-16 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white hover:bg-white/10 transition-all"
          >
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <button 
            onClick={captureAndScan}
            disabled={isScanning}
            className={`w-24 h-24 rounded-full border-4 flex items-center justify-center transition-all ${
              isScanning ? 'border-indigo-500 bg-indigo-500/20' : 'border-white bg-white/10 hover:scale-105 active:scale-95'
            }`}
          >
            {isScanning ? (
              <div className="w-10 h-10 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
            ) : (
              <div className="w-12 h-12 bg-white rounded-full"></div>
            )}
          </button>
        </div>

        <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.3em]">
          Dokument ausrichten und scannen
        </p>
      </div>

      <style>{`
        @keyframes scanLine {
          0% { transform: translateY(-200%); }
          100% { transform: translateY(200%); }
        }
        .animate-scanLine {
          animation: scanLine 2s linear infinite;
        }
      `}</style>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GERMAN_VOICES } from '../constants';
import { generateSpeech } from '../services/gemini';
import { decode, decodeAudioData, createWavBlob } from '../utils/audio';
import { CameraScanner } from './CameraScanner';

interface WordTiming {
  word: string;
  start: number;
  end: number;
}

export const VoiceStudio: React.FC = () => {
  const [text, setText] = useState('');
  const [selectedVoice, setSelectedVoice] = useState(GERMAN_VOICES[0]);
  const [isLoading, setIsLoading] = useState(false);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [lastAudioBase64, setLastAudioBase64] = useState<string | null>(null);
  const [currentWordIndex, setCurrentWordIndex] = useState(-1);
  const [favorites, setFavorites] = useState<string[]>(() => {
    const saved = localStorage.getItem('deutsch-ki-favorites');
    return saved ? JSON.parse(saved) : [];
  });

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const previewSourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const startTimeRef = useRef<number>(0);
  const wordTimingsRef = useRef<WordTiming[]>([]);
  const animationFrameRef = useRef<number>(0);

  useEffect(() => {
    localStorage.setItem('deutsch-ki-favorites', JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
      cancelAnimationFrame(animationFrameRef.current);
    };
  }, []);

  const words = useMemo(() => {
    return text.split(/(\s+)/).filter(Boolean);
  }, [text]);

  const favoriteVoices = useMemo(() => {
    return GERMAN_VOICES.filter(v => favorites.includes(v.id));
  }, [favorites]);

  const toggleFavorite = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setFavorites(prev => 
      prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]
    );
  };

  const stopAllAudio = () => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); } catch (e) {}
      sourceNodeRef.current = null;
    }
    if (previewSourceNodeRef.current) {
      try { previewSourceNodeRef.current.stop(); } catch (e) {}
      previewSourceNodeRef.current = null;
    }
    setIsPlaying(false);
    setPreviewingVoiceId(null);
    setCurrentWordIndex(-1);
    cancelAnimationFrame(animationFrameRef.current);
  };

  const handlePreview = async (e: React.MouseEvent, voice: typeof GERMAN_VOICES[0]) => {
    e.stopPropagation();
    if (previewingVoiceId === voice.id) {
      stopAllAudio();
      return;
    }

    stopAllAudio();
    setPreviewingVoiceId(voice.id);

    try {
      const base64 = await generateSpeech(voice.previewSnippet, voice.geminiVoice);

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);

      previewSourceNodeRef.current = source;
      source.start();
      source.onended = () => setPreviewingVoiceId(null);
    } catch (err: any) {
      setError("Preview konnte nicht geladen werden.");
      setPreviewingVoiceId(null);
    }
  };

  const updateHighlight = () => {
    if (!audioContextRef.current || !isPlaying) return;

    const elapsed = audioContextRef.current.currentTime - startTimeRef.current;
    const timings = wordTimingsRef.current;

    let foundIndex = -1;
    for (let i = 0; i < timings.length; i++) {
      if (elapsed >= timings[i].start && elapsed <= timings[i].end) {
        foundIndex = i;
        break;
      }
    }

    if (foundIndex !== currentWordIndex) {
      setCurrentWordIndex(foundIndex);
    }

    if (elapsed < (timings[timings.length - 1]?.end || 0)) {
      animationFrameRef.current = requestAnimationFrame(updateHighlight);
    } else {
      setIsPlaying(false);
      setCurrentWordIndex(-1);
    }
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;

    setIsLoading(true);
    setError(null);
    setLastAudioBase64(null);
    stopAllAudio();

    try {
      const base64 = await generateSpeech(text, selectedVoice.geminiVoice);
      setLastAudioBase64(base64);

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const duration = audioBuffer.duration;

      const textWords = words.filter(w => !/^\s+$/.test(w));
      const totalChars = textWords.join('').length;
      let currentOffset = 0;

      wordTimingsRef.current = textWords.map(word => {
        const wordWeight = word.length / (totalChars || 1);
        const wordDuration = wordWeight * duration;
        const timing = { word, start: currentOffset, end: currentOffset + wordDuration };
        currentOffset += wordDuration;
        return timing;
      });

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);

      sourceNodeRef.current = source;
      startTimeRef.current = ctx.currentTime;
      source.start();
      setIsPlaying(true);
      animationFrameRef.current = requestAnimationFrame(updateHighlight);

      source.onended = () => {
        setIsPlaying(false);
        setCurrentWordIndex(-1);
      };
    } catch (err: any) {
      setError(err.message || 'Ein Fehler ist aufgetreten.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDownload = () => {
    if (!lastAudioBase64) return;
    const pcmData = decode(lastAudioBase64);
    const blob = createWavBlob(pcmData, 24000);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Deutsch-KI_${selectedVoice.name.replace(/\s+/g, '_')}_320kbps.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-12 animate-fadeIn max-w-5xl mx-auto">
      {/* Scanner Overlay */}
      {showScanner && (
        <CameraScanner 
          onTextScanned={(scannedText) => setText(prev => prev ? `${prev}\n${scannedText}` : scannedText)}
          onClose={() => setShowScanner(false)}
        />
      )}

      {/* Redesigned Manuscript Area */}
      <section className="relative group">
        <div className="absolute -inset-1.5 bg-gradient-to-br from-indigo-500 via-purple-600 to-cyan-500 rounded-[2.5rem] blur opacity-20 group-hover:opacity-40 transition duration-1000"></div>
        <div className="relative bg-slate-900/60 backdrop-blur-3xl p-10 rounded-[2.5rem] border border-white/5 shadow-[0_25px_50px_-12px_rgba(0,0,0,0.5)] overflow-hidden min-h-[400px]">

          <div className="absolute inset-0 opacity-[0.03] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>

          <div className="flex justify-between items-center mb-8">
            <div className="flex flex-col gap-1">
              <h3 className="text-xs font-black text-indigo-400/80 uppercase tracking-[0.3em]">Audio Manuskript</h3>
              <div className="h-0.5 w-12 bg-indigo-500/50 rounded-full"></div>
            </div>
            <div className="flex items-center gap-3">
              <button 
                onClick={() => setShowScanner(true)}
                className="flex items-center gap-2 px-4 py-2 rounded-xl bg-white/5 border border-white/10 text-white hover:bg-white/10 transition-all group/btn"
              >
                <svg className="w-4 h-4 text-indigo-400 group-hover/btn:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
                </svg>
                <span className="text-[10px] font-black uppercase tracking-widest">Dokument scannen</span>
              </button>
              <div className={`px-3 py-1 rounded-full border border-white/5 text-[10px] font-mono transition-colors ${isPlaying ? 'text-emerald-400 bg-emerald-400/10' : 'text-slate-500'}`}>
                {isPlaying ? 'LIVE_PLAYBACK' : 'MANUAL_INPUT'}
              </div>
            </div>
          </div>

          <div className="relative w-full min-h-[220px]">
            {isPlaying && (
              <div className="absolute inset-0 z-10 text-white text-3xl font-light leading-relaxed pointer-events-none overflow-y-auto whitespace-pre-wrap tracking-tight">
                {words.map((part, idx) => {
                  const isWhitespace = /^\s+$/.test(part);
                  const wordList = words.filter(w => !/^\s+$/.test(w));
                  const wordOnlyIndex = wordList.indexOf(part);
                  const isSpoken = !isWhitespace && wordOnlyIndex === currentWordIndex;
                  return (
                    <span key={idx} className={`transition-all duration-300 ${isSpoken ? 'text-indigo-400 font-normal drop-shadow-[0_0_15px_rgba(129,140,248,0.9)] scale-110 inline-block animate-pulse' : 'opacity-20 blur-[1px]'}`}>
                      {part}
                    </span>
                  );
                })}
              </div>
            )}
            <textarea
              className={`w-full bg-transparent border-none focus:ring-0 p-0 text-white text-3xl font-light placeholder-slate-800 h-full min-h-[220px] resize-none leading-relaxed tracking-tight transition-all duration-700 ${isPlaying ? 'opacity-0 scale-95' : 'opacity-100 scale-100'}`}
              placeholder="Beginnen Sie hier mit Ihrem Text oder scannen Sie ein Dokument..."
              value={text}
              onChange={(e) => setText(e.target.value)}
              disabled={isPlaying}
              spellCheck={false}
            />
          </div>

          <div className="mt-8 flex flex-col gap-6 border-t border-white/5 pt-8">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`w-2.5 h-2.5 rounded-full transition-all duration-1000 ${isPlaying ? 'bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.8)]' : text.length > 0 ? 'bg-indigo-500 shadow-[0_0_10px_rgba(99,102,241,0.6)]' : 'bg-slate-700'}`}></div>
                <span className="text-[10px] text-slate-500 font-black tracking-widest uppercase">
                  {isPlaying ? 'Synthese aktiv' : text.length > 0 ? 'Bereit zum Rendern' : 'Warten auf Input'}
                </span>
              </div>
              <div className="flex items-center gap-6">
                <span className="text-[10px] text-slate-600 font-mono tabular-nums">{text.length} / 5000</span>
                <button onClick={() => { stopAllAudio(); setText(''); }} className="text-[10px] text-slate-500 hover:text-red-400 transition-colors uppercase font-black tracking-widest px-2">Clear</button>
              </div>
            </div>
            <div className="h-0.5 w-full bg-white/5 rounded-full overflow-hidden">
               <div className="h-full bg-indigo-500/50 transition-all duration-500" style={{ width: `${Math.min((text.length / 5000) * 100, 100)}%` }}></div>
            </div>
          </div>
        </div>
      </section>

      {/* Favorites */}
      {favoriteVoices.length > 0 && (
        <section className="animate-fadeIn">
          <div className="flex items-baseline justify-between mb-4 px-4">
            <h3 className="text-[10px] font-black text-indigo-400/60 uppercase tracking-[0.3em]">Quick Access</h3>
          </div>
          <div className="flex flex-wrap gap-3 px-4">
            {favoriteVoices.map(voice => (
              <button
                key={voice.id}
                onClick={() => setSelectedVoice(voice)}
                className={`px-5 py-2.5 rounded-2xl border transition-all flex items-center gap-3 group relative overflow-hidden ${selectedVoice.id === voice.id ? 'bg-indigo-500/10 border-indigo-500/50 text-white shadow-[0_0_20px_rgba(99,102,241,0.1)]' : 'bg-slate-900/40 border-slate-800 text-slate-500 hover:border-slate-700 hover:text-slate-300'}`}
              >
                <div className={`w-1.5 h-1.5 rounded-full ${voice.gender === 'male' ? 'bg-cyan-500' : 'bg-pink-500'}`}></div>
                <span className="text-xs font-bold tracking-tight">{voice.name}</span>
                <span className="text-[10px] opacity-40 group-hover:opacity-100 transition-opacity font-mono tracking-tighter uppercase">{voice.persona.split(' ')[1]}</span>
              </button>
            ))}
          </div>
        </section>
      )}

      {/* Voice Catalogue */}
      <section>
        <div className="flex items-baseline justify-between mb-8 px-4">
          <h3 className="text-xl font-bold text-white tracking-tight">Künstler Ensemble</h3>
          <span className="text-[10px] text-slate-500 font-black uppercase tracking-[0.3em] opacity-40">Stimm-Katalog</span>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {GERMAN_VOICES.map((voice) => {
            const isFavorite = favorites.includes(voice.id);
            const isMale = voice.gender === 'male';
            return (
              <button
                key={voice.id}
                onClick={() => setSelectedVoice(voice)}
                className={`relative p-7 rounded-3xl border transition-all duration-500 text-left group overflow-hidden ${selectedVoice.id === voice.id ? 'bg-white/10 border-indigo-500/60 shadow-[0_0_40px_rgba(99,102,241,0.15)]' : 'bg-slate-900/40 border-slate-800/50 hover:border-slate-600 hover:bg-white/5'}`}
              >
                <div className={`absolute top-0 left-0 w-1 h-full transition-all duration-700 ${isMale ? 'bg-cyan-500/30' : 'bg-pink-500/30'} ${selectedVoice.id === voice.id ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}></div>
                <div className="relative z-10">
                  <div className="flex justify-between items-start mb-4">
                    <div className={`text-[9px] font-black uppercase tracking-[0.2em] ${isMale ? 'text-cyan-400' : 'text-pink-400'}`}>{voice.persona}</div>
                    <div className="flex gap-2">
                      <button onClick={(e) => toggleFavorite(e, voice.id)} className={`p-1.5 transition-all ${isFavorite ? 'text-indigo-400 scale-110' : 'text-slate-700 hover:text-indigo-300'}`}>
                        <svg className="w-4 h-4 fill-current" viewBox="0 0 24 24"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>
                      </button>
                      <button onClick={(e) => handlePreview(e, voice)} className={`p-1.5 rounded-xl border transition-all ${previewingVoiceId === voice.id ? 'bg-indigo-500 border-indigo-400 text-white animate-pulse' : 'bg-slate-800/80 border-white/5 text-slate-500 hover:text-white hover:border-white/20'}`}>
                        {previewingVoiceId === voice.id ? (
                          <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
                        ) : (
                          <svg className="w-3.5 h-3.5 translate-x-0.5" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                        )}
                      </button>
                    </div>
                  </div>
                  <h4 className={`font-bold text-xl mb-1.5 transition-colors ${selectedVoice.id === voice.id ? 'text-white' : 'text-slate-300 group-hover:text-white'}`}>{voice.name}</h4>
                  <p className="text-[11px] text-slate-500 leading-relaxed line-clamp-2 italic opacity-80 group-hover:opacity-100">{voice.description}</p>
                </div>
              </button>
            );
          })}
        </div>
      </section>

      {/* Render Actions */}
      <div className="flex flex-col sm:flex-row gap-5 pt-8">
        <button onClick={handleGenerate} disabled={isLoading || !text.trim()} className={`relative flex-[2.5] group overflow-hidden rounded-[2rem] p-px transition-all duration-700 ${isLoading || !text.trim() ? 'opacity-40 grayscale pointer-events-none' : 'hover:scale-[1.01] active:scale-[0.98]'}`}>
          <div className="absolute inset-0 bg-gradient-to-r from-indigo-600 via-purple-600 to-cyan-500 animate-gradient-x"></div>
          <div className="relative bg-slate-950/90 rounded-[calc(2rem-1px)] py-7 flex items-center justify-center gap-5 transition-all group-hover:bg-transparent backdrop-blur-xl">
            {isLoading ? (
              <div className="flex items-center gap-4">
                <div className="w-6 h-6 border-2 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
                <span className="font-black text-white text-lg tracking-[0.4em] uppercase">Rendere Audio...</span>
              </div>
            ) : (
              <div className="flex items-center gap-5">
                <div className="w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center group-hover:bg-white/20 transition-colors">
                  <svg className="w-6 h-6 text-white fill-white" viewBox="0 0 24 24"><path d="M8 5v14l11-7z" /></svg>
                </div>
                <span className="font-black text-white text-2xl tracking-[0.2em] uppercase">Klang erschaffen</span>
              </div>
            )}
          </div>
        </button>

        <div className="flex flex-1 gap-5">
          {lastAudioBase64 && (
            <button onClick={handleDownload} className="flex-1 px-8 rounded-[2rem] border border-white/10 bg-white/5 hover:bg-white/10 text-white font-black tracking-[0.2em] uppercase transition-all flex items-center justify-center gap-4 group relative overflow-hidden backdrop-blur-md">
              <div className="absolute inset-0 bg-indigo-500/20 translate-y-full group-hover:translate-y-0 transition-transform duration-500"></div>
              <svg className="w-6 h-6 relative z-10 group-hover:translate-y-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              <span className="relative z-10 text-sm">Save</span>
            </button>
          )}
          {isPlaying && (
            <button onClick={stopAllAudio} className="px-10 rounded-[2rem] border border-red-500/40 bg-red-500/10 text-red-400 font-black tracking-widest uppercase hover:bg-red-500 hover:text-white transition-all animate-pulse flex items-center justify-center shadow-[0_0_30px_rgba(239,68,68,0.2)]">Stop</button>
          )}
        </div>
      </div>
      {error && <div className="bg-red-950/20 border border-red-500/30 p-8 rounded-3xl text-center text-red-400 text-sm font-black tracking-widest uppercase backdrop-blur-xl animate-shake">{error}</div>}
    </div>
  );
};

{
  "name": "Deutsch-KI Super App",
  "description": "Eine erstklassige Anwendung zur Konvertierung von deutschem Text in hochwertige Sprache mit Gemini 2.5 Flash.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { GERMAN_VOICES } from '../constants';
import { generateSpeech } from '../services/gemini';
import { decode, decodeAudioData, createWavBlob, encode } from '../utils/audio';
import { CameraScanner } from './CameraScanner';

interface WordTiming {
  word: string;
  start: number;
  end: number;
}

export const VoiceStudio: React.FC = () => {
  const [text, setText] = useState('');
  const [selectedVoice, setSelectedVoice] = useState(GERMAN_VOICES[0]);
  const [isLoading, setIsLoading] = useState(false);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isDictating, setIsDictating] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [lastAudioBase64, setLastAudioBase64] = useState<string | null>(null);
  const [currentWordIndex, setCurrentWordIndex] = useState(-1);
  const [favorites, setFavorites] = useState<string[]>(() => {
    const saved = localStorage.getItem('deutsch-ki-favorites');
    return saved ? JSON.parse(saved) : [];
  });

  const audioContextRef = useRef<AudioContext | null>(null);
  const dictationAudioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const previewSourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const startTimeRef = useRef<number>(0);
  const wordTimingsRef = useRef<WordTiming[]>([]);
  const animationFrameRef = useRef<number>(0);
  const liveSessionRef = useRef<any>(null);

  useEffect(() => {
    localStorage.setItem('deutsch-ki-favorites', JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    return () => {
      if (audioContextRef.current) audioContextRef.current.close();
      if (dictationAudioContextRef.current) dictationAudioContextRef.current.close();
      cancelAnimationFrame(animationFrameRef.current);
      if (liveSessionRef.current) liveSessionRef.current.close();
    };
  }, []);

  const words = useMemo(() => {
    return text.split(/(\s+)/).filter(Boolean);
  }, [text]);

  const favoriteVoices = useMemo(() => {
    return GERMAN_VOICES.filter(v => favorites.includes(v.id));
  }, [favorites]);

  const toggleFavorite = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setFavorites(prev => 
      prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]
    );
  };

  const stopAllAudio = () => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); } catch (e) {}
      sourceNodeRef.current = null;
    }
    if (previewSourceNodeRef.current) {
      try { previewSourceNodeRef.current.stop(); } catch (e) {}
      previewSourceNodeRef.current = null;
    }
    setIsPlaying(false);
    setPreviewingVoiceId(null);
    setCurrentWordIndex(-1);
    cancelAnimationFrame(animationFrameRef.current);
  };

  const startDictation = async () => {
    if (isDictating) {
      stopDictation();
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      dictationAudioContextRef.current = audioCtx;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsDictating(true);
            const source = audioCtx.createMediaStreamSource(stream);
            const scriptProcessor = audioCtx.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(audioCtx.destination);
          },
          onmessage: (message) => {
            if (message.serverContent?.inputTranscription) {
              const textChunk = message.serverContent.inputTranscription.text;
              setText(prev => prev + textChunk);
            }
          },
          onerror: () => stopDictation(),
          onclose: () => stopDictation(),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          systemInstruction: 'Transkribiere das gesprochene Deutsch präzise in Text. Gib nur den transkribierten Text zurück.',
        },
      });

      liveSessionRef.current = await sessionPromise;
    } catch (err) {
      setError("Mikrofon konnte nicht gestartet werden.");
      setIsDictating(false);
    }
  };

  const stopDictation = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.close();
      liveSessionRef.current = null;
    }
    if (dictationAudioContextRef.current) {
      dictationAudioContextRef.current.close();
      dictationAudioContextRef.current = null;
    }
    setIsDictating(false);
  };

  const handlePreview = async (e: React.MouseEvent, voice: typeof GERMAN_VOICES[0]) => {
    e.stopPropagation();
    if (previewingVoiceId === voice.id) {
      stopAllAudio();
      return;
    }

    stopAllAudio();
    setPreviewingVoiceId(voice.id);

    try {
      const base64 = await generateSpeech(voice.previewSnippet, voice.geminiVoice);

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);

      previewSourceNodeRef.current = source;
      source.start();
      source.onended = () => setPreviewingVoiceId(null);
    } catch (err: any) {
      setError("Preview konnte nicht geladen werden.");
      setPreviewingVoiceId(null);
    }
  };

  const updateHighlight = () => {
    if (!audioContextRef.current || !isPlaying) return;

    const elapsed = audioContextRef.current.currentTime - startTimeRef.current;
    const timings = wordTimingsRef.current;

    let foundIndex = -1;
    for (let i = 0; i < timings.length; i++) {
      if (elapsed >= timings[i].start && elapsed <= timings[i].end) {
        foundIndex = i;
        break;
      }
    }

    if (foundIndex !== currentWordIndex) {
      setCurrentWordIndex(foundIndex);
    }

    if (elapsed < (timings[timings.length - 1]?.end || 0)) {
      animationFrameRef.current = requestAnimationFrame(updateHighlight);
    } else {
      setIsPlaying(false);
      setCurrentWordIndex(-1);
    }
  };

  const handleGenerate = async () => {
    if (!text.trim()) return;

    setIsLoading(true);
    setError(null);
    setLastAudioBase64(null);
    stopAllAudio();

    try {
      const base64 = await generateSpeech(text, selectedVoice.geminiVoice);
      setLastAudioBase64(base64);

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const duration = audioBuffer.duration;

      const textWords = words.filter(w => !/^\s+$/.test(w));
      const totalChars = textWords.join('').length;
      let currentOffset = 0;

      wordTimingsRef.current = textWords.map(word => {
        const wordWeight = word.length / (totalChars || 1);
        const wordDuration = wordWeight * duration;
        const timing = { word, start: currentOffset, end: currentOffset + wordDuration };
        currentOffset += wordDuration;
        return timing;
      });

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);

      sourceNodeRef.current = source;
      startTimeRef.current = ctx.currentTime;
      source.start();
      setIsPlaying(true);
      animationFrameRef.current = requestAnimationFrame(updateHighlight);

      source.onended = () => {
        setIsPlaying(false);
        setCurrentWordIndex(-1);
      };
    } catch (err: any) {
      setError(err.message || 'Ein Fehler ist aufgetreten.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDownload = () => {
    if (!lastAudioBase64) return;
    const pcmData = decode(lastAudioBase64);
    const blob = createWavBlob(pcmData, 24000);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Deutsch-KI_${selectedVoice.name.replace(/\s+/g, '_')}_320kbps.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-12 animate-fadeIn max-w-5xl mx-auto">
      {showScanner && (
        <CameraScanner 
          onTextScanned={(scannedText) => setText(prev => prev ? `${prev}\n${scannedText}` : scannedText)}
          onClose={() => setShowScanner(false)}
        />
      )}

      {/* Redesigned Manuscript Area */}
      <section className="relative group">
        <div className={`absolute -inset-1.5 rounded-[2.5rem] blur transition duration-1000 ${isDictating ? 'bg-red-500 opacity-40 animate-pulse' : 'bg-gradient-to-br from-indigo-500 via-purple-600 to-cyan-500 opacity-20 group-hover:opacity-40'}`}></div>
        <div className="relative bg-slate-900/60 backdrop-blur-3xl p-10 rounded-[2.5rem] border border-white/5 shadow-[0_25px_50px_-12px_rgba(0,0,0,0.5)] overflow-hidden min-h-[400px]">

          <div className="absolute inset-0 opacity-[0.03] pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/stardust.png')]"></div>

          <div className="flex justify-between items-center mb-8 relative z-20">
            <div className="flex flex-col gap-1">
              <h3 className="text-xs font-black text-indigo-400/80 uppercase tracking-[0.3em]">Audio Manuskript</h3>
              <div className="h-0.5 w-12 bg-indigo-500/50 rounded-full"></div>
            </div>
            <div className="flex items-center gap-3">
              {/* Voice Creation Button */}
              <button 
                onClick={startDictation}
                className={`flex items-center gap-2 px-4 py-2 rounded-xl border transition-all group/mic ${isDictating ? 'bg-red-500/20 border-red-500 text-red-400' : 'bg-white/5 border-white/10 text-white hover:bg-white/10'}`}
              >
                <div className={`w-2 h-2 rounded-full ${isDictating ? 'bg-red-500 animate-ping' : 'bg-slate-500'}`}></div>
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                </svg>
                <span className="text-[10px] font-black uppercase tracking-widest">{isDictating ? 'Aufnahme...' : 'Sprechen'}</span>
