                </div>
              </div>
            )}

            <textarea
              className={`w-full h-full min-h-[300px] bg-transparent border-none outline-none resize-none text-slate-300 placeholder-slate-700 selection:bg-indigo-500/30 ${isPlaying ? 'opacity-0' : 'opacity-100'}`}
              placeholder="// Geben Sie Ihren Text ein oder initialisieren Sie den Scan-Vorgang..."
              value={text}
              onChange={(e) => setText(e.target.value)}
