            />
          </div>

          {/* Terminal Status Bar */}
          <div className="bg-white/5 border-t border-white/5 px-4 py-2 flex justify-between items-center text-[10px] font-mono text-slate-500 uppercase tracking-widest">
             <div>CHAR_COUNT: {text.length}</div>
             <div className="flex items-center gap-3">
               <span className={isDictating ? "text-red-400 animate-pulse" : ""}>{isDictating ? "● REC" : "MIC_OFF"}</span>
               <span className="w-px h-3 bg-white/10"></span>
               <span>{isPlaying ? "PLAYBACK_ACTIVE" : "IDLE"}</span>
             </div>
          </div>
        </div>
      </section>

      {/* --- CONTROL MATRIX --- */}
      <section className="flex flex-col sm:flex-row gap-6">
         {/* Main Generate Button */}
         <button 
           onClick={handleGenerate} 
           disabled={isLoading || !text.trim()} 
           className={`relative flex-[3] group overflow-hidden rounded-xl bg-white/5 border border-white/10 hover:border-indigo-500/50 transition-all duration-300 ${isLoading || !text.trim() ? 'opacity-50 grayscale cursor-not-allowed' : 'hover:shadow-[0_0_40px_rgba(99,102,241,0.15)]'}`}
         >
           <div className="absolute inset-0 bg-gradient-to-r from-indigo-900/40 via-purple-900/40 to-cyan-900/40 opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
           <div className="relative px-8 py-6 flex items-center justify-center gap-6">
             {isLoading ? (
               <>
                 <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                 <span className="text-sm font-black text-white tracking-[0.2em] uppercase">Processing...</span>
