                   <svg className="w-6 h-6 fill-current" viewBox="0 0 24 24"><path d="M8 5v14l11-7z" /></svg>
                 </div>
                 <div className="text-left">
                   <div className="text-lg font-black text-white tracking-widest uppercase group-hover:text-indigo-200 transition-colors">Generate Audio</div>
                   <div className="text-[10px] text-indigo-400 font-mono">RENDER_MODE: HIGH_FIDELITY</div>
                 </div>
               </>
             )}
