         </button>

         {/* Playback Controls */}
         <div className="flex-[2] flex gap-3">
            <button 
              onClick={() => setIsLoopEnabled(!isLoopEnabled)}
              className={`relative flex-1 rounded-xl border flex flex-col items-center justify-center gap-2 transition-all duration-500 overflow-hidden group ${
                isLoopEnabled 
                  ? 'bg-indigo-500/20 border-indigo-400 text-white shadow-[0_0_20px_rgba(99,102,241,0.3)]' 
                  : 'bg-white/5 border-white/10 text-slate-500 hover:bg-white/10 hover:border-white/20'
              }`}
            >
              {/* Animated Background Glow for Active State */}
              {isLoopEnabled && (
                <div className="absolute inset-0 bg-gradient-to-tr from-indigo-500/0 via-indigo-500/10 to-cyan-500/0 animate-pulse"></div>
              )}

              <svg 
                className={`w-6 h-6 relative z-10 transition-all duration-700 ${isLoopEnabled ? 'rotate-180 text-cyan-300 drop-shadow-[0_0_10px_rgba(34,211,238,0.6)]' : 'group-hover:text-slate-300'}`} 
                fill="none" 
                viewBox="0 0 24 24" 
                stroke="currentColor"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
              </svg>
              <span className={`text-[9px] font-black uppercase tracking-widest relative z-10 transition-colors ${isLoopEnabled ? 'text-indigo-200' : ''}`}>
                Loop
              </span>
            </button>

            {isPlaying && (
              <button onClick={() => stopAllAudio(true)} className="flex-1 rounded-xl border border-red-500/30 bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white transition-all flex flex-col items-center justify-center gap-2 animate-pulse">
                <div className="w-4 h-4 rounded-sm bg-current"></div>
                <span className="text-[9px] font-black uppercase tracking-widest">Stop</span>
              </button>
            )}

            {lastAudioBase64 && !isPlaying && (
              <button onClick={handleDownload} className="flex-1 rounded-xl border border-emerald-500/30 bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500 hover:text-white transition-all flex flex-col items-center justify-center gap-2">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                <span className="text-[9px] font-black uppercase tracking-widest">WAV</span>
              </button>
            )}
         </div>
      </section>

      {error && (
        <div className="bg-red-500/10 border border-red-500/50 p-4 rounded-lg flex items-center gap-4 text-red-200 animate-shake">
          <svg className="w-6 h-6 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          <span className="text-sm font-mono">{error}</span>
        </div>
      )}

      {/* --- ARTIST PROFILES --- */}
      <section>
        <div className="flex items-end justify-between mb-8 px-2 border-b border-white/5 pb-4">
           <div>
             <h3 className="text-xl font-bold text-white tracking-tight">Künstler Ensemble</h3>
             <p className="text-[10px] text-slate-500 font-mono uppercase tracking-widest mt-1">Select Voice Persona</p>
           </div>
           {favoriteVoices.length > 0 && <span className="text-[10px] text-indigo-400 font-mono">{favoriteVoices.length} FAVORITES ACTIVE</span>}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
          {GERMAN_VOICES.map((voice) => {
            const isSelected = selectedVoice.id === voice.id;
            const isPlayingPreview = previewingVoiceId === voice.id;

            return (
              <button
                key={voice.id}
                onClick={() => setSelectedVoice(voice)}
                className={`relative group h-full text-left rounded-xl p-5 border transition-all duration-300 flex flex-col justify-between overflow-hidden ${isSelected ? 'bg-white/5 border-indigo-500 ring-1 ring-indigo-500/50' : 'bg-[#0a0c10] border-white/5 hover:border-white/20'}`}
              >
                {/* Active Indicator Line */}
                <div className={`absolute top-0 left-0 w-full h-0.5 bg-gradient-to-r from-indigo-500 to-cyan-500 transition-opacity ${isSelected ? 'opacity-100' : 'opacity-0'}`}></div>

                <div>
                  <div className="flex justify-between items-start mb-3">
                    <span className={`text-[9px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded ${voice.gender === 'male' ? 'bg-cyan-900/30 text-cyan-400' : 'bg-fuchsia-900/30 text-fuchsia-400'}`}>
                      {voice.gender === 'male' ? 'M' : 'F'}
                    </span>
                    <div className="flex gap-2">
                      <div onClick={(e) => toggleFavorite(e, voice.id)} className={`cursor-pointer transition-colors ${favorites.includes(voice.id) ? 'text-yellow-400' : 'text-slate-700 hover:text-yellow-400'}`}>
                        <svg className="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24"><path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z" /></svg>
                      </div>
                      <div onClick={(e) => handlePreview(e, voice)} className={`cursor-pointer transition-all ${isPlayingPreview ? 'text-indigo-400 animate-pulse' : 'text-slate-600 hover:text-white'}`}>
                        {isPlayingPreview ? (
                          <svg className="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
                        ) : (
                          <svg className="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                        )}
                      </div>
                    </div>
                  </div>

                  <h4 className={`text-lg font-bold mb-1 transition-colors ${isSelected ? 'text-white' : 'text-slate-300 group-hover:text-white'}`}>{voice.name}</h4>
                  <div className="text-[10px] text-indigo-400 font-mono mb-3 truncate">{voice.persona}</div>
                  <p className="text-[11px] text-slate-500 leading-relaxed line-clamp-3 opacity-80 group-hover:opacity-100 transition-opacity">
                    {voice.description}
                  </p>
                </div>
              </button>
            );
          })}
        </div>
      </section>
    </div>
  );
};

import { GoogleGenAI, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates high-quality German speech from text.
 */
export const generateSpeech = async (text: string, voiceName: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Bitte sprich diesen deutschen Text mit maximaler künstlerischer Qualität, klarer Artikulation und emotionalem Ausdruck: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audiogenerierung fehlgeschlagen. Keine Daten empfangen.");
  return base64Audio;
};

// Fix: Added missing export 'extractTextFromImage' to handle OCR requests from CameraScanner.
/**
 * Extracts text from an image using Gemini vision capabilities.
 */
export const extractTextFromImage = async (base64Image: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: "image/jpeg",
            data: base64Image,
          },
        },
        { text: "Extrahiere den gesamten Text aus diesem Bild. Gib nur den erkannten Text zurück ohne zusätzliche Kommentare." },
      ],
    },
  });

  return response.text || "";
};

/**
 * Translates text from German to Arabic.
 */
export const translateText = async (text: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [{ parts: [{ text: `Translate the following German text into Arabic. Return strictly only the translated Arabic text, no markdown, no explanations.\n\nText: ${text}` }] }],
  });
  return response.text?.trim() || "";
};

import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { GERMAN_VOICES } from '../constants';
import { generateSpeech, translateText } from '../services/gemini';
import { decode, decodeAudioData, createWavBlob, encode } from '../utils/audio';
import { CameraScanner } from './CameraScanner';

interface WordTiming {
  word: string;
  start: number;
  end: number;
}

export const VoiceStudio: React.FC = () => {
  // State
  const [text, setText] = useState('');
  const [arabicText, setArabicText] = useState<string | null>(null);
  const [selectedVoice, setSelectedVoice] = useState(GERMAN_VOICES[0]);
  const [isLoading, setIsLoading] = useState(false);
  const [isTranslating, setIsTranslating] = useState(false);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isDictating, setIsDictating] = useState(false);
  const [isLoopEnabled, setIsLoopEnabled] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [lastAudioBase64, setLastAudioBase64] = useState<string | null>(null);
  const [currentWordIndex, setCurrentWordIndex] = useState(-1);
  const [favorites, setFavorites] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('deutsch-ki-favorites');
      return saved ? JSON.parse(saved) : [];
    } catch { return []; }
  });

  // Refs for audio logic & Critical Mode synchronization
  const audioContextRef = useRef<AudioContext | null>(null);
  const dictationAudioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const previewSourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const currentAudioBufferRef = useRef<AudioBuffer | null>(null);
  const startTimeRef = useRef<number>(0);
  const wordTimingsRef = useRef<WordTiming[]>([]);
  const animationFrameRef = useRef<number>(0);
  const liveSessionRef = useRef<any>(null);

  // Critical: Refs to track state inside event listeners
  const isLoopEnabledRef = useRef(isLoopEnabled);
  const isPlayingRef = useRef(isPlaying);

  // Sync refs with state
  useEffect(() => { isLoopEnabledRef.current = isLoopEnabled; }, [isLoopEnabled]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { localStorage.setItem('deutsch-ki-favorites', JSON.stringify(favorites)); }, [favorites]);

  // Cleanup on mount/unmount
  useEffect(() => {
    return () => {
      stopAllAudio(true);
      if (audioContextRef.current) audioContextRef.current.close();
      if (dictationAudioContextRef.current) dictationAudioContextRef.current.close();
      if (liveSessionRef.current) liveSessionRef.current.close();
    };
  }, []);

  const words = useMemo(() => text.split(/(\s+)/).filter(Boolean), [text]);
  const favoriteVoices = useMemo(() => GERMAN_VOICES.filter(v => favorites.includes(v.id)), [favorites, GERMAN_VOICES]);

  const toggleFavorite = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setFavorites(prev => prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]);
  };

  const stopAllAudio = useCallback((manual: boolean = true) => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); sourceNodeRef.current.disconnect(); } catch (e) {}
      sourceNodeRef.current = null;
    }
    if (previewSourceNodeRef.current) {
      try { previewSourceNodeRef.current.stop(); previewSourceNodeRef.current.disconnect(); } catch (e) {}
      previewSourceNodeRef.current = null;
    }
    cancelAnimationFrame(animationFrameRef.current);

    if (manual) {
      setIsPlaying(false);
      setCurrentWordIndex(-1);
    }
    setPreviewingVoiceId(null);
  }, []);

  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    return audioContextRef.current;
  };

  // --- Core Audio Logic ---

  const playBuffer = useCallback((buffer: AudioBuffer) => {
    const ctx = getAudioContext();
    if (ctx.state === 'suspended') ctx.resume();

    stopAllAudio(false); // Stop previous node, but keep 'isPlaying' true logically

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);

    sourceNodeRef.current = source;
    startTimeRef.current = ctx.currentTime;

    // UI Sync
    setIsPlaying(true);
    setCurrentWordIndex(-1);

    // Start Animation Loop
    const tick = () => {
      if (!ctx || !isPlayingRef.current) return;
      const elapsed = ctx.currentTime - startTimeRef.current;
      const timings = wordTimingsRef.current;

      let foundIndex = -1;
      // Critical optimization: reverse search might be faster for long texts, but linear is safe for now
      for (let i = 0; i < timings.length; i++) {
        if (elapsed >= timings[i].start && elapsed <= timings[i].end) {
          foundIndex = i;
          break;
        }
      }

      setCurrentWordIndex(foundIndex);

      if (elapsed < buffer.duration + 0.5) { // +0.5s buffer for safety
        animationFrameRef.current = requestAnimationFrame(tick);
      }
    };
    animationFrameRef.current = requestAnimationFrame(tick);

    source.start();

    // Critical: Handle Loop vs Stop
    source.onended = () => {
      // Check refs for fresh state
      if (isLoopEnabledRef.current && isPlayingRef.current) {
        playBuffer(buffer); // Recursive restart
      } else {
        setIsPlaying(false);
        setCurrentWordIndex(-1);
      }
    };
  }, [stopAllAudio]);

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsLoading(true);
    setError(null);
    setLastAudioBase64(null);
    currentAudioBufferRef.current = null;
    stopAllAudio(true);

    try {
      const base64 = await generateSpeech(text, selectedVoice.geminiVoice);
      setLastAudioBase64(base64);

      const ctx = getAudioContext();
      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      currentAudioBufferRef.current = audioBuffer;

      // Calculate Timings (Linear Interpolation based on char count)
      const duration = audioBuffer.duration;
      const textWords = words.filter(w => !/^\s+$/.test(w));
      const totalChars = textWords.join('').length;
      let currentOffset = 0;

      wordTimingsRef.current = textWords.map(word => {
        const wordWeight = word.length / (totalChars || 1);
        const wordDuration = wordWeight * duration;
        const timing = { word, start: currentOffset, end: currentOffset + wordDuration };
        currentOffset += wordDuration;
        return timing;
      });

      playBuffer(audioBuffer);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Synthese fehlgeschlagen.');
    } finally {
      setIsLoading(false);
    }
  };

  const handlePreview = async (e: React.MouseEvent, voice: typeof GERMAN_VOICES[0]) => {
    e.stopPropagation();
    if (previewingVoiceId === voice.id) {
      stopAllAudio(true);
      return;
    }

    stopAllAudio(true);
    setPreviewingVoiceId(voice.id);

    try {
      const base64 = await generateSpeech(voice.previewSnippet, voice.geminiVoice);
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      previewSourceNodeRef.current = source;
      source.start();
      source.onended = () => setPreviewingVoiceId(null);
    } catch (err) {
      setPreviewingVoiceId(null);
    }
  };

  const handleDownload = () => {
    if (!lastAudioBase64) return;
    const blob = createWavBlob(decode(lastAudioBase64), 24000);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Deutsch-KI_${selectedVoice.name}_${Date.now()}.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleTranslate = async () => {
    if (!text.trim()) return;
    setIsTranslating(true);
    setArabicText(null);
    try {
      const translated = await translateText(text);
      setArabicText(translated);
    } catch (err) {
      setError("Übersetzung fehlgeschlagen.");
    } finally {
      setIsTranslating(false);
    }
  };

  // --- Dictation Logic ---
  const startDictation = async () => {
    if (isDictating) { stopDictation(); return; }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      dictationAudioContextRef.current = audioCtx;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsDictating(true);
            const source = audioCtx.createMediaStreamSource(stream);
            const scriptProcessor = audioCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(input.length);
              for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioCtx.destination);
          },
          onmessage: (m) => {
            if (m.serverContent?.inputTranscription?.text) setText(p => p + m.serverContent!.inputTranscription!.text);
          },
          onerror: () => stopDictation(),
          onclose: () => stopDictation(),
        },
        config: { responseModalities: [Modality.AUDIO], inputAudioTranscription: {}, systemInstruction: 'Transcribe precise German.' },
      });
      liveSessionRef.current = await sessionPromise;
    } catch (err) { setError("Mikrofon Zugriff verweigert."); setIsDictating(false); }
  };

  const stopDictation = () => {
    liveSessionRef.current?.close();
    dictationAudioContextRef.current?.close();
    setIsDictating(false);
  };

  return (
    <div className="space-y-16 animate-fadeIn max-w-6xl mx-auto font-sans">
