               </div>
             )}

             <div className="flex bg-white/5 rounded-lg p-1 border border-white/10">
                <button onClick={startDictation} className={`p-2 rounded transition-all ${isDictating ? 'bg-red-500/20 text-red-400 animate-pulse' : 'hover:bg-white/5 text-slate-400 hover:text-white'}`} title="Spracheingabe">
