import { GoogleGenAI, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates high-quality German speech from text.
 */
export const generateSpeech = async (text: string, voiceName: string) => {
  const ai = getAI();

  // Advanced Prompt Engineering for "320 kbps" feel
  // We instruct the model to simulate a high-end studio recording environment
  const studioPrompt = `
    [Regie-Anweisung: Höchste Audio-Fidelity. Simuliere eine professionelle Studio-Aufnahme (Neumann U87 Mikrofon-Charakteristik). 
    Stimme: Warm, resonant, rauschfrei, 320kbps Qualität.
    Sprechweise: Natürlich, mit perfekter Betonung, Pausen und emotionaler Tiefe. Keine digitalen Artefakte.]

    Zu sprechender Text:
    ${text}
  `;

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: studioPrompt }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audiogenerierung fehlgeschlagen. Keine Daten empfangen.");
  return base64Audio;
};

// Fix: Added missing export 'extractTextFromImage' to handle OCR requests from CameraScanner.
/**
 * Extracts text from an image using Gemini vision capabilities.
 */
export const extractTextFromImage = async (base64Image: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: "image/jpeg",
            data: base64Image,
          },
        },
        { text: "Extrahiere den gesamten Text aus diesem Bild. Gib nur den erkannten Text zurück ohne zusätzliche Kommentare." },
      ],
    },
  });

  return response.text || "";
};

/**
 * Translates text from German to Arabic.
 */
export const translateText = async (text: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [{ parts: [{ text: `Translate the following German text into Arabic. Return strictly only the translated Arabic text, no markdown, no explanations.\n\nText: ${text}` }] }],
  });
  return response.text?.trim() || "";
};

import { GoogleGenAI, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates high-quality German speech from text.
 * Supports standard presets and 'Neural Cloning' via custom persona descriptions.
 */
export const generateSpeech = async (text: string, voiceName: string, cloningPersona?: string) => {
  const ai = getAI();

  let systemPrompt = "";

  if (cloningPersona) {
    // Neural Cloning Mode: Forces the model to mimic a specific target
    systemPrompt = `
      [SYSTEM-INSTRUKTION: NEURAL VOICE CLONING AKTIV]
      [ZIEL-PERSONA: "${cloningPersona}"]

      Anweisungen an die Audio-Engine:
      1. Imitiere täuschend echt die Stimme, Sprechweise, den Duktus und den Akzent der ZIEL-PERSONA.
      2. Übernimm charakteristische Atempausen, Betonungen und Tonalität.
      3. Audio-Qualität: STUDIO MASTER (320kbps äquivalent), warm, nah, ohne Hall.
      4. Falls die Persona eine berühmte Persönlichkeit ist, nutze das gesamte Wissen über deren Stimme.

      Zu sprechender Text:
      ${text}
    `;
  } else {
    // Standard High-Fidelity Mode
    systemPrompt = `
      [Regie-Anweisung: Höchste Audio-Fidelity. Simuliere eine professionelle Studio-Aufnahme (Neumann U87 Mikrofon-Charakteristik). 
      Stimme: Warm, resonant, rauschfrei, 320kbps Qualität.
      Sprechweise: Natürlich, mit perfekter Betonung, Pausen und emotionaler Tiefe. Keine digitalen Artefakte.]

      Zu sprechender Text:
      ${text}
    `;
  }

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: systemPrompt }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audiogenerierung fehlgeschlagen. Keine Daten empfangen.");
  return base64Audio;
};

// Fix: Added missing export 'extractTextFromImage' to handle OCR requests from CameraScanner.
/**
 * Extracts text from an image using Gemini vision capabilities.
 */
export const extractTextFromImage = async (base64Image: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: "image/jpeg",
            data: base64Image,
          },
        },
        { text: "Extrahiere den gesamten Text aus diesem Bild. Gib nur den erkannten Text zurück ohne zusätzliche Kommentare." },
      ],
    },
  });

  return response.text || "";
};

/**
 * Translates text from German to Arabic.
 */
export const translateText = async (text: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [{ parts: [{ text: `Translate the following German text into Arabic. Return strictly only the translated Arabic text, no markdown, no explanations.\n\nText: ${text}` }] }],
  });
  return response.text?.trim() || "";
};

import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { GERMAN_VOICES } from '../constants';
import { generateSpeech, translateText } from '../services/gemini';
import { decode, decodeAudioData, createWavBlob, encode } from '../utils/audio';
import { CameraScanner } from './CameraScanner';

interface WordTiming {
  word: string;
  start: number;
  end: number;
}

export const VoiceStudio: React.FC = () => {
  // State
  const [text, setText] = useState('');
  const [arabicText, setArabicText] = useState<string | null>(null);
  const [selectedVoice, setSelectedVoice] = useState(GERMAN_VOICES[0]);
  const [cloningPersona, setCloningPersona] = useState('');
  const [isCloningMode, setIsCloningMode] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isTranslating, setIsTranslating] = useState(false);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isDictating, setIsDictating] = useState(false);
  const [isLoopEnabled, setIsLoopEnabled] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [lastAudioBase64, setLastAudioBase64] = useState<string | null>(null);
  const [currentWordIndex, setCurrentWordIndex] = useState(-1);
  const [favorites, setFavorites] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('deutsch-ki-favorites');
      return saved ? JSON.parse(saved) : [];
    } catch { return []; }
  });

  // Refs for audio logic & Critical Mode synchronization
  const audioContextRef = useRef<AudioContext | null>(null);
  const dictationAudioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const previewSourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const currentAudioBufferRef = useRef<AudioBuffer | null>(null);
  const startTimeRef = useRef<number>(0);
  const wordTimingsRef = useRef<WordTiming[]>([]);
  const animationFrameRef = useRef<number>(0);
  const liveSessionRef = useRef<any>(null);

  // Critical: Refs to track state inside event listeners
  const isLoopEnabledRef = useRef(isLoopEnabled);
  const isPlayingRef = useRef(isPlaying);

  // Sync refs with state
  useEffect(() => { isLoopEnabledRef.current = isLoopEnabled; }, [isLoopEnabled]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { localStorage.setItem('deutsch-ki-favorites', JSON.stringify(favorites)); }, [favorites]);

  // Cleanup on mount/unmount
  useEffect(() => {
    return () => {
      stopAllAudio(true);
      if (audioContextRef.current) audioContextRef.current.close();
      if (dictationAudioContextRef.current) dictationAudioContextRef.current.close();
      if (liveSessionRef.current) liveSessionRef.current.close();
    };
  }, []);

  const words = useMemo(() => text.split(/(\s+)/).filter(Boolean), [text]);
  const favoriteVoices = useMemo(() => GERMAN_VOICES.filter(v => favorites.includes(v.id)), [favorites, GERMAN_VOICES]);

  const toggleFavorite = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setFavorites(prev => prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]);
  };

  const stopAllAudio = useCallback((manual: boolean = true) => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); sourceNodeRef.current.disconnect(); } catch (e) {}
      sourceNodeRef.current = null;
    }
    if (previewSourceNodeRef.current) {
      try { previewSourceNodeRef.current.stop(); previewSourceNodeRef.current.disconnect(); } catch (e) {}
      previewSourceNodeRef.current = null;
    }
    cancelAnimationFrame(animationFrameRef.current);

    if (manual) {
      setIsPlaying(false);
      setCurrentWordIndex(-1);
    }
    setPreviewingVoiceId(null);
  }, []);

  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    return audioContextRef.current;
  };

  // --- Core Audio Logic ---

  const playBuffer = useCallback((buffer: AudioBuffer) => {
    const ctx = getAudioContext();
    if (ctx.state === 'suspended') ctx.resume();

    stopAllAudio(false); // Stop previous node, but keep 'isPlaying' true logically

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);

    sourceNodeRef.current = source;
    startTimeRef.current = ctx.currentTime;

    // UI Sync
    setIsPlaying(true);
    setCurrentWordIndex(-1);

    // Start Animation Loop
    const tick = () => {
      if (!ctx || !isPlayingRef.current) return;
      const elapsed = ctx.currentTime - startTimeRef.current;
      const timings = wordTimingsRef.current;

      let foundIndex = -1;
      // Critical optimization: reverse search might be faster for long texts, but linear is safe for now
      for (let i = 0; i < timings.length; i++) {
        if (elapsed >= timings[i].start && elapsed <= timings[i].end) {
          foundIndex = i;
          break;
        }
      }

      setCurrentWordIndex(foundIndex);

      if (elapsed < buffer.duration + 0.5) { // +0.5s buffer for safety
        animationFrameRef.current = requestAnimationFrame(tick);
      }
    };
    animationFrameRef.current = requestAnimationFrame(tick);

    source.start();

    // Critical: Handle Loop vs Stop
    source.onended = () => {
      // Check refs for fresh state
      if (isLoopEnabledRef.current && isPlayingRef.current) {
        playBuffer(buffer); // Recursive restart
      } else {
        setIsPlaying(false);
        setCurrentWordIndex(-1);
      }
    };
  }, [stopAllAudio]);

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsLoading(true);
    setError(null);
    setLastAudioBase64(null);
    currentAudioBufferRef.current = null;
    stopAllAudio(true);

    try {
      // Pass cloning persona if mode is active
      const cloningTarget = isCloningMode && cloningPersona.trim() ? cloningPersona : undefined;
      const base64 = await generateSpeech(text, selectedVoice.geminiVoice, cloningTarget);

      setLastAudioBase64(base64);

      const ctx = getAudioContext();
      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      currentAudioBufferRef.current = audioBuffer;

      // Calculate Timings (Linear Interpolation based on char count)
      const duration = audioBuffer.duration;
      const textWords = words.filter(w => !/^\s+$/.test(w));
      const totalChars = textWords.join('').length;
      let currentOffset = 0;

      wordTimingsRef.current = textWords.map(word => {
        const wordWeight = word.length / (totalChars || 1);
        const wordDuration = wordWeight * duration;
        const timing = { word, start: currentOffset, end: currentOffset + wordDuration };
        currentOffset += wordDuration;
        return timing;
      });

      playBuffer(audioBuffer);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Synthese fehlgeschlagen.');
    } finally {
      setIsLoading(false);
    }
  };

  const handlePreview = async (e: React.MouseEvent, voice: typeof GERMAN_VOICES[0]) => {
    e.stopPropagation();
    if (previewingVoiceId === voice.id) {
      stopAllAudio(true);
      return;
    }

    stopAllAudio(true);
    setPreviewingVoiceId(voice.id);

    try {
      // Previews are always standard mode (no cloning) to hear the base voice
      const base64 = await generateSpeech(voice.previewSnippet, voice.geminiVoice);
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      previewSourceNodeRef.current = source;
      source.start();
      source.onended = () => setPreviewingVoiceId(null);
    } catch (err) {
      setPreviewingVoiceId(null);
    }
  };

  const handleDownload = () => {
    if (!lastAudioBase64) return;
    const blob = createWavBlob(decode(lastAudioBase64), 24000);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Deutsch-KI_${isCloningMode ? 'CLONE' : selectedVoice.name}_${Date.now()}.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleTranslate = async () => {
    if (!text.trim()) return;
    setIsTranslating(true);
    setArabicText(null);
    try {
      const translated = await translateText(text);
      setArabicText(translated);
    } catch (err) {
      setError("Übersetzung fehlgeschlagen.");
    } finally {
      setIsTranslating(false);
    }
  };

  // --- Dictation Logic ---
  const startDictation = async () => {
    if (isDictating) { stopDictation(); return; }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      dictationAudioContextRef.current = audioCtx;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsDictating(true);
            const source = audioCtx.createMediaStreamSource(stream);
            const scriptProcessor = audioCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(input.length);
              for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioCtx.destination);
          },
          onmessage: (m) => {
            if (m.serverContent?.inputTranscription?.text) setText(p => p + m.serverContent!.inputTranscription!.text);
          },
          onerror: () => stopDictation(),
          onclose: () => stopDictation(),
        },
        config: { responseModalities: [Modality.AUDIO], inputAudioTranscription: {}, systemInstruction: 'Transcribe precise German.' },
      });
      liveSessionRef.current = await sessionPromise;
    } catch (err) { setError("Mikrofon Zugriff verweigert."); setIsDictating(false); }
  };

  const stopDictation = () => {
    liveSessionRef.current?.close();
    dictationAudioContextRef.current?.close();
    setIsDictating(false);
  };

  return (
    <div className="space-y-16 animate-fadeIn max-w-6xl mx-auto font-sans">
      {showScanner && (
        <CameraScanner 
          onTextScanned={(t) => setText(p => p ? `${p}\n${t}` : t)}
          onClose={() => setShowScanner(false)}
        />
      )}

      {/* --- VISION & MANUSCRIPT TERMINAL --- */}
      <section className="relative">
        <div className="absolute inset-0 bg-indigo-500/5 blur-[100px] rounded-full"></div>

        {/* Terminal Header */}
        <div className="flex items-end justify-between mb-4 px-2">
           <div className="flex items-center gap-3">
             <div className="flex flex-col">
               <span className="text-[10px] text-indigo-400 font-mono tracking-widest uppercase mb-1">DATA_INPUT_STREAM</span>
               <h3 className="text-xl font-bold text-white tracking-tight">Terminal Manuskript</h3>
             </div>
           </div>

           <div className="flex items-center gap-2">
             {isLoopEnabled && (
               <div className="flex items-center gap-2 px-3 py-1.5 rounded bg-indigo-500/10 border border-indigo-500/40 text-[10px] font-mono text-indigo-300 animate-pulse shadow-[0_0_15px_rgba(99,102,241,0.2)]">
                 <span className="w-1.5 h-1.5 bg-indigo-400 rounded-full"></span>
                 LOOP_SEQUENCE
               </div>
             )}

             <div className="flex bg-white/5 rounded-lg p-1 border border-white/10">
                <button onClick={startDictation} className={`p-2 rounded transition-all ${isDictating ? 'bg-red-500/20 text-red-400 animate-pulse' : 'hover:bg-white/5 text-slate-400 hover:text-white'}`} title="Spracheingabe">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                </button>
                <button onClick={() => setShowScanner(true)} className="p-2 rounded hover:bg-white/5 text-slate-400 hover:text-white transition-all" title="Vision Scan">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                </button>
                <div className="w-px h-6 bg-white/10 mx-1 self-center"></div>
                <button onClick={handleTranslate} disabled={!text.trim() || isTranslating} className={`p-2 rounded transition-all ${isTranslating ? 'text-amber-400 animate-spin' : 'hover:bg-amber-500/10 text-slate-400 hover:text-amber-400'}`} title="Translate to Arabic">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129" /></svg>
                </button>
             </div>
           </div>
        </div>

        {/* Terminal Body */}
        <div className="relative group rounded-xl overflow-hidden border border-white/10 bg-[#05070a] shadow-2xl transition-all duration-500 hover:border-indigo-500/30">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-cyan-500 to-indigo-500 opacity-0 group-hover:opacity-100 transition-opacity"></div>

          <div className="relative min-h-[300px] p-6 font-mono text-lg leading-relaxed">
            {/* Playback Overlay */}
            {isPlaying && (
              <div className="absolute inset-0 z-20 bg-[#05070a]/80 backdrop-blur-sm p-6 overflow-y-auto pointer-events-none">
                <div className="flex flex-wrap gap-x-2 gap-y-1">
                  {words.map((part, idx) => {
                    const isWhitespace = /^\s+$/.test(part);
                    const wordList = words.filter(w => !/^\s+$/.test(w));
                    const wordOnlyIndex = wordList.indexOf(part);
                    const isSpoken = !isWhitespace && wordOnlyIndex === currentWordIndex;
                    return (
                      <span key={idx} className={`transition-all duration-100 ${isSpoken ? 'text-white bg-indigo-500/50 px-1 rounded shadow-[0_0_15px_rgba(99,102,241,0.5)] scale-110 font-bold' : 'text-slate-600'}`}>
                        {part}
                      </span>
                    );
                  })}
                </div>
              </div>
            )}

            <textarea
              className={`w-full h-full min-h-[300px] bg-transparent border-none outline-none resize-none text-slate-300 placeholder-slate-700 selection:bg-indigo-500/30 ${isPlaying ? 'opacity-0' : 'opacity-100'}`}
              placeholder="// Geben Sie Ihren Text ein oder initialisieren Sie den Scan-Vorgang..."
              value={text}
              onChange={(e) => setText(e.target.value)}
              disabled={isPlaying}
              spellCheck={false}
            />
          </div>

          {/* Terminal Status Bar */}
          <div className="bg-white/5 border-t border-white/5 px-4 py-2 flex justify-between items-center text-[10px] font-mono text-slate-500 uppercase tracking-widest">
             <div>CHAR_COUNT: {text.length}</div>
             <div className="flex items-center gap-3">
               <span className={isDictating ? "text-red-400 animate-pulse" : ""}>{isDictating ? "● REC" : "MIC_OFF"}</span>
               <span className="w-px h-3 bg-white/10"></span>
               <span>{isPlaying ? "PLAYBACK_ACTIVE" : "IDLE"}</span>
             </div>
          </div>
        </div>

        {/* Translation Output Module */}
        {arabicText && (
          <div className="mt-4 relative animate-fadeIn">
            <div className="absolute top-0 left-0 w-1 h-full bg-amber-500/50 rounded-l"></div>
            <div className="bg-[#080a0f] border border-white/5 rounded-r-xl p-6 relative overflow-hidden group/trans">
              <div className="absolute inset-0 bg-amber-500/5 opacity-0 group-hover/trans:opacity-100 transition-opacity pointer-events-none"></div>

              <div className="flex justify-between items-start mb-4">
                <span className="text-[10px] text-amber-500/80 font-mono tracking-widest uppercase">Translation_Output [Arabic]</span>
                <a 
                  href={`https://www.reverso.net/traduction-texte#sl=ger&tl=ara&text=${encodeURIComponent(text)}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex items-center gap-2 px-3 py-1.5 rounded-lg border border-amber-500/20 bg-amber-500/10 text-amber-400 hover:bg-amber-500 hover:text-white transition-all text-[10px] font-bold tracking-widest uppercase"
                >
                  <span>Verify [Reverso]</span>
                  <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                </a>
              </div>

              <div className="text-2xl text-slate-200 font-light leading-relaxed" dir="rtl">
                {arabicText}
              </div>
            </div>
          </div>
        )}
      </section>

      {/* --- CONTROL MATRIX --- */}
      <section className="flex flex-col sm:flex-row gap-6">
         {/* Main Generate Button */}
         <button 
           onClick={handleGenerate} 
           disabled={isLoading || !text.trim()} 
           className={`relative flex-[3] group overflow-hidden rounded-xl bg-white/5 border border-white/10 hover:border-indigo-500/50 transition-all duration-300 ${isLoading || !text.trim() ? 'opacity-50 grayscale cursor-not-allowed' : 'hover:shadow-[0_0_40px_rgba(99,102,241,0.15)]'}`}
         >
           <div className="absolute inset-0 bg-gradient-to-r from-indigo-900/40 via-purple-900/40 to-cyan-900/40 opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
           <div className="relative px-8 py-6 flex items-center justify-center gap-6">
             {isLoading ? (
               <>
                 <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                 <span className="text-sm font-black text-white tracking-[0.2em] uppercase">Processing...</span>
               </>
             ) : (
               <>
                 <div className="w-12 h-12 rounded-lg bg-indigo-500 text-white flex items-center justify-center shadow-lg group-hover:scale-110 transition-transform">
                   <svg className="w-6 h-6 fill-current" viewBox="0 0 24 24"><path d="M8 5v14l11-7z" /></svg>
                 </div>
                 <div className="text-left">
                   <div className="text-lg font-black text-white tracking-widest uppercase group-hover:text-indigo-200 transition-colors">{isCloningMode ? 'CLONE & GENERATE' : 'GENERATE AUDIO'}</div>
                   <div className="text-[10px] text-indigo-400 font-mono">RENDER_MODE: {isCloningMode ? 'NEURAL_CLONE' : 'HIGH_FIDELITY'}</div>
                 </div>
               </>
             )}
           </div>
         </button>

         {/* Playback Controls */}
         <div className="flex-[2] flex gap-3">
            <button 
              onClick={() => setIsLoopEnabled(!isLoopEnabled)}
              className={`relative flex-1 rounded-xl border flex flex-col items-center justify-center gap-2 transition-all duration-500 overflow-hidden group ${
                isLoopEnabled 
                  ? 'bg-indigo-500/20 border-indigo-400 text-white shadow-[0_0_20px_rgba(99,102,241,0.3)]' 
                  : 'bg-white/5 border-white/10 text-slate-500 hover:bg-white/10 hover:border-white/20'
              }`}
            >
              {/* Animated Background Glow for Active State */}
              {isLoopEnabled && (
                <div className="absolute inset-0 bg-gradient-to-tr from-indigo-500/0 via-indigo-500/10 to-cyan-500/0 animate-pulse"></div>
              )}

              <svg 
                className={`w-6 h-6 relative z-10 transition-all duration-700 ${isLoopEnabled ? 'rotate-180 text-cyan-300 drop-shadow-[0_0_10px_rgba(34,211,238,0.6)]' : 'group-hover:text-slate-300'}`} 
                fill="none" 
                viewBox="0 0 24 24" 
                stroke="currentColor"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
              </svg>
              <span className={`text-[9px] font-black uppercase tracking-widest relative z-10 transition-colors ${isLoopEnabled ? 'text-indigo-200' : ''}`}>
                Loop
              </span>
            </button>

            {isPlaying && (
              <button onClick={() => stopAllAudio(true)} className="flex-1 rounded-xl border border-red-500/30 bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white transition-all flex flex-col items-center justify-center gap-2 animate-pulse">
                <div className="w-4 h-4 rounded-sm bg-current"></div>
                <span className="text-[9px] font-black uppercase tracking-widest">Stop</span>
              </button>
            )}

            {lastAudioBase64 && !isPlaying && (
              <button onClick={handleDownload} className="flex-1 rounded-xl border border-emerald-500/30 bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500 hover:text-white transition-all flex flex-col items-center justify-center gap-2">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                <span className="text-[9px] font-black uppercase tracking-widest">WAV</span>
              </button>
            )}
         </div>
      </section>

      {error && (
        <div className="bg-red-500/10 border border-red-500/50 p-4 rounded-lg flex items-center gap-4 text-red-200 animate-shake">
          <svg className="w-6 h-6 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          <span className="text-sm font-mono">{error}</span>
        </div>
      )}

      {/* --- NEURAL VOICE CLONING LAB --- */}
      <section className="border-b border-white/5 pb-8">
         <div className="flex items-center justify-between mb-6 px-2">
            <div>
              <h3 className="text-xl font-bold text-white tracking-tight flex items-center gap-3">
                 Neural Voice Lab
                 <span className="text-[10px] bg-indigo-500/20 text-indigo-300 px-2 py-0.5 rounded border border-indigo-500/30 uppercase tracking-widest">Beta</span>
              </h3>
              <p className="text-[10px] text-slate-500 font-mono uppercase tracking-widest mt-1">Imitate Celebrity & Custom Personas</p>
            </div>

            <button 
              onClick={() => setIsCloningMode(!isCloningMode)}
              className={`relative px-4 py-2 rounded-lg border transition-all duration-300 flex items-center gap-3 ${isCloningMode ? 'bg-indigo-600 border-indigo-400 text-white shadow-[0_0_20px_rgba(99,102,241,0.5)]' : 'bg-white/5 border-white/10 text-slate-400 hover:border-white/30'}`}
            >
              <div className={`w-2 h-2 rounded-full ${isCloningMode ? 'bg-white animate-pulse' : 'bg-slate-500'}`}></div>
              <span className="text-xs font-bold tracking-widest uppercase">{isCloningMode ? 'Cloning Active' : 'Enable Cloning'}</span>
            </button>
         </div>

         <div className={`transition-all duration-500 overflow-hidden ${isCloningMode ? 'max-h-[300px] opacity-100' : 'max-h-0 opacity-0'}`}>
            <div className="bg-gradient-to-r from-indigo-900/10 to-cyan-900/10 border border-indigo-500/30 rounded-xl p-6 relative">
              {/* DNA Animation Background */}
              <div className="absolute inset-0 overflow-hidden opacity-20 pointer-events-none">
                 <div className="absolute top-[20%] left-0 w-full h-[1px] bg-indigo-500 animate-pulse"></div>
                 <div className="absolute top-[80%] left-0 w-full h-[1px] bg-cyan-500 animate-pulse" style={{animationDelay: '1s'}}></div>
              </div>

              <div className="relative z-10 flex flex-col md:flex-row gap-6 items-end">
                 <div className="flex-1 w-full">
                    <label className="block text-[10px] text-indigo-300 font-mono uppercase tracking-widest mb-2">
                      Target Voice DNA / Persona Link (e.g. "Morgan Freeman", "Sad Robot")
                    </label>
                    <div className="relative group">
                      <div className="absolute inset-0 bg-indigo-500/20 blur-sm rounded-lg group-focus-within:bg-indigo-500/40 transition-all"></div>
                      <input 
                        type="text" 
                        value={cloningPersona}
                        onChange={(e) => setCloningPersona(e.target.value)}
                        placeholder="Describe the voice or enter celebrity name..."
                        className="relative w-full bg-[#05070a] border border-indigo-500/30 rounded-lg px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500/50 font-mono text-sm shadow-xl"
                      />
                      <div className="absolute right-3 top-3 text-indigo-500/50">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
                      </div>
                    </div>
                 </div>

                 <div className="text-[10px] text-slate-500 max-w-xs leading-relaxed">
                   <strong className="text-white">Note:</strong> Uses advanced prompt engineering to mimic vocal characteristics. For best results, specify gender, age, and tone (e.g. "Old wise man with a scratchy voice").
                 </div>
              </div>
            </div>
         </div>
      </section>

      {/* --- ARTIST PROFILES (Dimmed when Cloning is Active) --- */}
      <section className={`transition-all duration-500 ${isCloningMode ? 'opacity-40 grayscale pointer-events-none filter blur-[1px]' : 'opacity-100'}`}>
        <div className="flex items-end justify-between mb-8 px-2 border-b border-white/5 pb-4">
           <div>
             <h3 className="text-xl font-bold text-white tracking-tight">Künstler Ensemble</h3>
             <p className="text-[10px] text-slate-500 font-mono uppercase tracking-widest mt-1">Select Base Voice Persona</p>
           </div>
           {favoriteVoices.length > 0 && <span className="text-[10px] text-indigo-400 font-mono">{favoriteVoices.length} FAVORITES ACTIVE</span>}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
          {GERMAN_VOICES.map((voice) => {
            const isSelected = selectedVoice.id === voice.id;
            const isPlayingPreview = previewingVoiceId === voice.id;

            return (
              <button
                key={voice.id}
                onClick={() => setSelectedVoice(voice)}
                className={`relative group h-full text-left rounded-xl p-5 border transition-all duration-300 flex flex-col justify-between overflow-hidden ${isSelected ? 'bg-white/5 border-indigo-500 ring-1 ring-indigo-500/50' : 'bg-[#0a0c10] border-white/5 hover:border-white/20'}`}
              >
                {/* Active Indicator Line */}
                <div className={`absolute top-0 left-0 w-full h-0.5 bg-gradient-to-r from-indigo-500 to-cyan-500 transition-opacity ${isSelected ? 'opacity-100' : 'opacity-0'}`}></div>

                <div>
                  <div className="flex justify-between items-start mb-3">
                    <span className={`text-[9px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded ${voice.gender === 'male' ? 'bg-cyan-900/30 text-cyan-400' : 'bg-fuchsia-900/30 text-fuchsia-400'}`}>
                      {voice.gender === 'male' ? 'M' : 'F'}
                    </span>
                    <div className="flex gap-2">
                      <div onClick={(e) => toggleFavorite(e, voice.id)} className={`cursor-pointer transition-colors ${favorites.includes(voice.id) ? 'text-yellow-400' : 'text-slate-700 hover:text-yellow-400'}`}>
                        <svg className="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24"><path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z" /></svg>
                      </div>
                      <div onClick={(e) => handlePreview(e, voice)} className={`cursor-pointer transition-all ${isPlayingPreview ? 'text-indigo-400 animate-pulse' : 'text-slate-600 hover:text-white'}`}>
                        {isPlayingPreview ? (
                          <svg className="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
                        ) : (
                          <svg className="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                        )}
                      </div>
                    </div>
                  </div>

                  <h4 className={`text-lg font-bold mb-1 transition-colors ${isSelected ? 'text-white' : 'text-slate-300 group-hover:text-white'}`}>{voice.name}</h4>
                  <div className="text-[10px] text-indigo-400 font-mono mb-3 truncate">{voice.persona}</div>
                  <p className="text-[11px] text-slate-500 leading-relaxed line-clamp-3 opacity-80 group-hover:opacity-100 transition-opacity">
                    {voice.description}
                  </p>
                </div>
              </button>
            );
          })}
        </div>
      </section>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { GERMAN_VOICES, CLONING_PRESETS } from '../constants';
import { generateSpeech, translateText } from '../services/gemini';
import { decode, decodeAudioData, createWavBlob, encode } from '../utils/audio';
import { CameraScanner } from './CameraScanner';

interface WordTiming {
  word: string;
  start: number;
  end: number;
}

export const VoiceStudio: React.FC = () => {
  // State
  const [text, setText] = useState('');
  const [arabicText, setArabicText] = useState<string | null>(null);
  const [selectedVoice, setSelectedVoice] = useState(GERMAN_VOICES[0]);
  const [cloningPersona, setCloningPersona] = useState('');
  const [isCloningMode, setIsCloningMode] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isTranslating, setIsTranslating] = useState(false);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isDictating, setIsDictating] = useState(false);
  const [isLoopEnabled, setIsLoopEnabled] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [lastAudioBase64, setLastAudioBase64] = useState<string | null>(null);
  const [currentWordIndex, setCurrentWordIndex] = useState(-1);
  const [favorites, setFavorites] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('deutsch-ki-favorites');
      return saved ? JSON.parse(saved) : [];
    } catch { return []; }
  });

  // Refs for audio logic & Critical Mode synchronization
  const audioContextRef = useRef<AudioContext | null>(null);
  const dictationAudioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const previewSourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const currentAudioBufferRef = useRef<AudioBuffer | null>(null);
  const startTimeRef = useRef<number>(0);
  const wordTimingsRef = useRef<WordTiming[]>([]);
  const animationFrameRef = useRef<number>(0);
  const liveSessionRef = useRef<any>(null);

  // Critical: Refs to track state inside event listeners
  const isLoopEnabledRef = useRef(isLoopEnabled);
  const isPlayingRef = useRef(isPlaying);

  // Sync refs with state
  useEffect(() => { isLoopEnabledRef.current = isLoopEnabled; }, [isLoopEnabled]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { localStorage.setItem('deutsch-ki-favorites', JSON.stringify(favorites)); }, [favorites]);

  // Cleanup on mount/unmount
  useEffect(() => {
    return () => {
      stopAllAudio(true);
      if (audioContextRef.current) audioContextRef.current.close();
      if (dictationAudioContextRef.current) dictationAudioContextRef.current.close();
      if (liveSessionRef.current) liveSessionRef.current.close();
    };
  }, []);

  const words = useMemo(() => text.split(/(\s+)/).filter(Boolean), [text]);
  const favoriteVoices = useMemo(() => GERMAN_VOICES.filter(v => favorites.includes(v.id)), [favorites, GERMAN_VOICES]);

  const toggleFavorite = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setFavorites(prev => prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]);
  };

  const stopAllAudio = useCallback((manual: boolean = true) => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); sourceNodeRef.current.disconnect(); } catch (e) {}
      sourceNodeRef.current = null;
    }
    if (previewSourceNodeRef.current) {
      try { previewSourceNodeRef.current.stop(); previewSourceNodeRef.current.disconnect(); } catch (e) {}
      previewSourceNodeRef.current = null;
    }
    cancelAnimationFrame(animationFrameRef.current);

    if (manual) {
      setIsPlaying(false);
      setCurrentWordIndex(-1);
    }
    setPreviewingVoiceId(null);
  }, []);

  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    return audioContextRef.current;
  };

  // --- Core Audio Logic ---

  const playBuffer = useCallback((buffer: AudioBuffer) => {
    const ctx = getAudioContext();
    if (ctx.state === 'suspended') ctx.resume();

    stopAllAudio(false); // Stop previous node, but keep 'isPlaying' true logically

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);

    sourceNodeRef.current = source;
    startTimeRef.current = ctx.currentTime;

    // UI Sync
    setIsPlaying(true);
    setCurrentWordIndex(-1);

    // Start Animation Loop
    const tick = () => {
      if (!ctx || !isPlayingRef.current) return;
      const elapsed = ctx.currentTime - startTimeRef.current;
      const timings = wordTimingsRef.current;

      let foundIndex = -1;
      // Critical optimization: reverse search might be faster for long texts, but linear is safe for now
      for (let i = 0; i < timings.length; i++) {
        if (elapsed >= timings[i].start && elapsed <= timings[i].end) {
          foundIndex = i;
          break;
        }
      }

      setCurrentWordIndex(foundIndex);

      if (elapsed < buffer.duration + 0.5) { // +0.5s buffer for safety
        animationFrameRef.current = requestAnimationFrame(tick);
      }
    };
    animationFrameRef.current = requestAnimationFrame(tick);

    source.start();

    // Critical: Handle Loop vs Stop
    source.onended = () => {
      // Check refs for fresh state
      if (isLoopEnabledRef.current && isPlayingRef.current) {
        playBuffer(buffer); // Recursive restart
      } else {
        setIsPlaying(false);
        setCurrentWordIndex(-1);
      }
    };
  }, [stopAllAudio]);

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsLoading(true);
    setError(null);
    setLastAudioBase64(null);
    currentAudioBufferRef.current = null;
    stopAllAudio(true);

    try {
      // Pass cloning persona if mode is active
      const cloningTarget = isCloningMode && cloningPersona.trim() ? cloningPersona : undefined;
      const base64 = await generateSpeech(text, selectedVoice.geminiVoice, cloningTarget);

      setLastAudioBase64(base64);

      const ctx = getAudioContext();
      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      currentAudioBufferRef.current = audioBuffer;

      // Calculate Timings (Linear Interpolation based on char count)
      const duration = audioBuffer.duration;
      const textWords = words.filter(w => !/^\s+$/.test(w));
      const totalChars = textWords.join('').length;
      let currentOffset = 0;

      wordTimingsRef.current = textWords.map(word => {
        const wordWeight = word.length / (totalChars || 1);
        const wordDuration = wordWeight * duration;
        const timing = { word, start: currentOffset, end: currentOffset + wordDuration };
        currentOffset += wordDuration;
        return timing;
      });

      playBuffer(audioBuffer);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Synthese fehlgeschlagen.');
    } finally {
      setIsLoading(false);
    }
  };

  const handlePreview = async (e: React.MouseEvent, voice: typeof GERMAN_VOICES[0]) => {
    e.stopPropagation();
    if (previewingVoiceId === voice.id) {
      stopAllAudio(true);
      return;
    }

    stopAllAudio(true);
    setPreviewingVoiceId(voice.id);

    try {
      // Previews are always standard mode (no cloning) to hear the base voice
      const base64 = await generateSpeech(voice.previewSnippet, voice.geminiVoice);
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      previewSourceNodeRef.current = source;
      source.start();
      source.onended = () => setPreviewingVoiceId(null);
    } catch (err) {
      setPreviewingVoiceId(null);
    }
  };

  const handleDownload = () => {
    if (!lastAudioBase64) return;
    const blob = createWavBlob(decode(lastAudioBase64), 24000);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Deutsch-KI_${isCloningMode ? 'CLONE' : selectedVoice.name}_${Date.now()}.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleTranslate = async () => {
    if (!text.trim()) return;
    setIsTranslating(true);
    setArabicText(null);
    try {
      const translated = await translateText(text);
      setArabicText(translated);
    } catch (err) {
      setError("Übersetzung fehlgeschlagen.");
    } finally {
      setIsTranslating(false);
    }
  };

  // --- Dictation Logic ---
  const startDictation = async () => {
    if (isDictating) { stopDictation(); return; }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      dictationAudioContextRef.current = audioCtx;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsDictating(true);
            const source = audioCtx.createMediaStreamSource(stream);
            const scriptProcessor = audioCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(input.length);
              for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioCtx.destination);
          },
          onmessage: (m) => {
            if (m.serverContent?.inputTranscription?.text) setText(p => p + m.serverContent!.inputTranscription!.text);
          },
          onerror: () => stopDictation(),
          onclose: () => stopDictation(),
        },
        config: { responseModalities: [Modality.AUDIO], inputAudioTranscription: {}, systemInstruction: 'Transcribe precise German.' },
      });
      liveSessionRef.current = await sessionPromise;
    } catch (err) { setError("Mikrofon Zugriff verweigert."); setIsDictating(false); }
  };

  const stopDictation = () => {
    liveSessionRef.current?.close();
    dictationAudioContextRef.current?.close();
    setIsDictating(false);
  };

  return (
    <div className="space-y-16 animate-fadeIn max-w-6xl mx-auto font-sans">
      {showScanner && (
        <CameraScanner 
          onTextScanned={(t) => setText(p => p ? `${p}\n${t}` : t)}
          onClose={() => setShowScanner(false)}
        />
      )}

      {/* --- VISION & MANUSCRIPT TERMINAL --- */}
      <section className="relative">
        <div className="absolute inset-0 bg-indigo-500/5 blur-[100px] rounded-full"></div>

        {/* Terminal Header */}
        <div className="flex items-end justify-between mb-4 px-2">
           <div className="flex items-center gap-3">
             <div className="flex flex-col">
               <span className="text-[10px] text-indigo-400 font-mono tracking-widest uppercase mb-1">DATA_INPUT_STREAM</span>
               <h3 className="text-xl font-bold text-white tracking-tight">Terminal Manuskript</h3>
             </div>
           </div>

           <div className="flex items-center gap-2">
             {isLoopEnabled && (
               <div className="flex items-center gap-2 px-3 py-1.5 rounded bg-indigo-500/10 border border-indigo-500/40 text-[10px] font-mono text-indigo-300 animate-pulse shadow-[0_0_15px_rgba(99,102,241,0.2)]">
                 <span className="w-1.5 h-1.5 bg-indigo-400 rounded-full"></span>
                 LOOP_SEQUENCE
               </div>
             )}

             <div className="flex bg-white/5 rounded-lg p-1 border border-white/10">
                <button onClick={startDictation} className={`p-2 rounded transition-all ${isDictating ? 'bg-red-500/20 text-red-400 animate-pulse' : 'hover:bg-white/5 text-slate-400 hover:text-white'}`} title="Spracheingabe">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                </button>
                <button onClick={() => setShowScanner(true)} className="p-2 rounded hover:bg-white/5 text-slate-400 hover:text-white transition-all" title="Vision Scan">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                </button>
                <div className="w-px h-6 bg-white/10 mx-1 self-center"></div>
                <button onClick={handleTranslate} disabled={!text.trim() || isTranslating} className={`p-2 rounded transition-all ${isTranslating ? 'text-amber-400 animate-spin' : 'hover:bg-amber-500/10 text-slate-400 hover:text-amber-400'}`} title="Translate to Arabic">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129" /></svg>
                </button>
             </div>
           </div>
        </div>

        {/* Terminal Body */}
        <div className="relative group rounded-xl overflow-hidden border border-white/10 bg-[#05070a] shadow-2xl transition-all duration-500 hover:border-indigo-500/30">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-indigo-500 via-cyan-500 to-indigo-500 opacity-0 group-hover:opacity-100 transition-opacity"></div>

          <div className="relative min-h-[300px] p-6 font-mono text-lg leading-relaxed">
            {/* Playback Overlay */}
            {isPlaying && (
