                        <svg className="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24"><path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z" /></svg>
                      </div>
                      <div onClick={(e) => handlePreview(e, voice)} className={`cursor-pointer transition-all ${isPlayingPreview ? 'text-indigo-400 animate-pulse' : 'text-slate-600 hover:text-white'}`}>
                        {isPlayingPreview ? (
                          <svg className="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>
                        ) : (
                          <svg className="w-3.5 h-3.5 fill-current" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                        )}
                      </div>
                    </div>
                  </div>

                  <h4 className={`text-lg font-bold mb-1 transition-colors ${isSelected ? 'text-white' : 'text-slate-300 group-hover:text-white'}`}>{voice.name}</h4>
                  <div className="text-[10px] text-indigo-400 font-mono mb-3 truncate">{voice.persona}</div>
                  <p className="text-[11px] text-slate-500 leading-relaxed line-clamp-3 opacity-80 group-hover:opacity-100 transition-opacity">
                    {voice.description}
                  </p>
                </div>
              </button>
            );
          })}
        </div>
      </section>
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo, useCallback } from 'react';
import { GoogleGenAI, Modality } from '@google/genai';
import { GERMAN_VOICES, CLONING_PRESETS } from '../constants';
import { generateSpeech, translateText } from '../services/gemini';
import { decode, decodeAudioData, createWavBlob, encode } from '../utils/audio';
import { CameraScanner } from './CameraScanner';

interface WordTiming {
  word: string;
  start: number;
  end: number;
}

export const VoiceStudio: React.FC = () => {
  // State
  const [text, setText] = useState('');
  const [arabicText, setArabicText] = useState<string | null>(null);
  const [selectedVoice, setSelectedVoice] = useState(GERMAN_VOICES[0]);
  const [cloningPersona, setCloningPersona] = useState('');
  const [isCloningMode, setIsCloningMode] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isTranslating, setIsTranslating] = useState(false);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isDictating, setIsDictating] = useState(false);
  const [isLoopEnabled, setIsLoopEnabled] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [lastAudioBase64, setLastAudioBase64] = useState<string | null>(null);
  const [currentWordIndex, setCurrentWordIndex] = useState(-1);
  const [favorites, setFavorites] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('deutsch-ki-favorites');
      return saved ? JSON.parse(saved) : [];
    } catch { return []; }
  });

  // Refs for audio logic
  const audioContextRef = useRef<AudioContext | null>(null);
  const dictationAudioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const previewSourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const currentAudioBufferRef = useRef<AudioBuffer | null>(null);
  const startTimeRef = useRef<number>(0);
  const wordTimingsRef = useRef<WordTiming[]>([]);
  const animationFrameRef = useRef<number>(0);
  const liveSessionRef = useRef<any>(null);

  // Refs for UI
  const overlayRef = useRef<HTMLDivElement>(null);
  const wordRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const visualizerCanvasRef = useRef<HTMLCanvasElement>(null);

  // Critical: Refs to track state inside event listeners
  const isLoopEnabledRef = useRef(isLoopEnabled);
  const isPlayingRef = useRef(isPlaying);

  // Sync refs with state
  useEffect(() => { isLoopEnabledRef.current = isLoopEnabled; }, [isLoopEnabled]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { localStorage.setItem('deutsch-ki-favorites', JSON.stringify(favorites)); }, [favorites]);

  // Clear word refs when text changes to prevent stale indices
  useEffect(() => { wordRefs.current = []; }, [text]);

  // Auto-scroll effect
  useEffect(() => {
    if (isPlaying && currentWordIndex >= 0 && wordRefs.current[currentWordIndex]) {
      wordRefs.current[currentWordIndex]?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
        inline: 'nearest'
      });
    }
  }, [currentWordIndex, isPlaying]);

  // Cleanup on mount/unmount
  useEffect(() => {
    return () => {
      stopAllAudio(true);
      if (audioContextRef.current) audioContextRef.current.close();
      if (dictationAudioContextRef.current) dictationAudioContextRef.current.close();
      if (liveSessionRef.current) liveSessionRef.current.close();
    };
  }, []);

  const words = useMemo(() => text.split(/(\s+)/), [text]);
  const favoriteVoices = useMemo(() => GERMAN_VOICES.filter(v => favorites.includes(v.id)), [favorites, GERMAN_VOICES]);

  const toggleFavorite = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setFavorites(prev => prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]);
  };

  const stopAllAudio = useCallback((manual: boolean = true) => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); sourceNodeRef.current.disconnect(); } catch (e) {}
      sourceNodeRef.current = null;
    }
    if (previewSourceNodeRef.current) {
      try { previewSourceNodeRef.current.stop(); previewSourceNodeRef.current.disconnect(); } catch (e) {}
      previewSourceNodeRef.current = null;
    }
    cancelAnimationFrame(animationFrameRef.current);

    if (manual) {
      setIsPlaying(false);
      setCurrentWordIndex(-1);
      // Clear visualizer
      if (visualizerCanvasRef.current) {
        const ctx = visualizerCanvasRef.current.getContext('2d');
        if (ctx) ctx.clearRect(0, 0, visualizerCanvasRef.current.width, visualizerCanvasRef.current.height);
      }
    }
    setPreviewingVoiceId(null);
  }, []);

  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    return audioContextRef.current;
  };

  // --- Visualizer Logic ---
  const drawVisualizer = () => {
    if (!analyserRef.current || !visualizerCanvasRef.current) return;

    const canvas = visualizerCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    analyserRef.current.getByteFrequencyData(dataArray);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const barWidth = (canvas.width / bufferLength) * 2.5;
    let barHeight;
    let x = 0;

    // Gradient for bars
    const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
    gradient.addColorStop(0, '#818cf8'); // Indigo 400
    gradient.addColorStop(1, '#22d3ee'); // Cyan 400

    ctx.fillStyle = gradient;

    for (let i = 0; i < bufferLength; i++) {
      barHeight = dataArray[i] / 2; // Scale down slightly
      // Rounded tops
      ctx.fillRect(x, canvas.height - barHeight, barWidth, barHeight);
      x += barWidth + 1;
    }
  };

  // --- Core Audio Logic ---

  const playBuffer = useCallback((buffer: AudioBuffer) => {
    const ctx = getAudioContext();
    if (ctx.state === 'suspended') ctx.resume();

    stopAllAudio(false);

    const source = ctx.createBufferSource();
    source.buffer = buffer;

    // Connect Analyser for Visualizer
    const analyser = ctx.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;
    source.connect(analyser);
    analyser.connect(ctx.destination);

    sourceNodeRef.current = source;
    analyserRef.current = analyser;
    startTimeRef.current = ctx.currentTime;

    setIsPlaying(true);
    setCurrentWordIndex(-1);

    // Animation Loop (Timing + Visualizer)
    const tick = () => {
      if (!ctx || !isPlayingRef.current) return;
      const elapsed = ctx.currentTime - startTimeRef.current;
      const timings = wordTimingsRef.current;

      // Update Word Index
      let foundIndex = -1;
      for (let i = 0; i < timings.length; i++) {
        if (elapsed >= timings[i].start && elapsed <= timings[i].end) {
          foundIndex = i;
          break;
        }
      }
      setCurrentWordIndex(foundIndex);

      // Draw Visualizer
      drawVisualizer();

      if (elapsed < buffer.duration + 0.5) {
        animationFrameRef.current = requestAnimationFrame(tick);
      } else {
        // Clear visualizer at end
        if (visualizerCanvasRef.current) {
          const c = visualizerCanvasRef.current.getContext('2d');
          c?.clearRect(0, 0, visualizerCanvasRef.current.width, visualizerCanvasRef.current.height);
        }
      }
    };
    animationFrameRef.current = requestAnimationFrame(tick);

    source.start();

    source.onended = () => {
      if (isLoopEnabledRef.current && isPlayingRef.current) {
        playBuffer(buffer);
      } else {
        setIsPlaying(false);
        setCurrentWordIndex(-1);
      }
    };
  }, [stopAllAudio]);

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsLoading(true);
    setError(null);
    setLastAudioBase64(null);
    currentAudioBufferRef.current = null;
    stopAllAudio(true);

    try {
      const cloningTarget = isCloningMode && cloningPersona.trim() ? cloningPersona : undefined;
      const base64 = await generateSpeech(text, selectedVoice.geminiVoice, cloningTarget);

      setLastAudioBase64(base64);

      const ctx = getAudioContext();
      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      currentAudioBufferRef.current = audioBuffer;

      // Calculate Timings (Linear)
      const duration = audioBuffer.duration;
      const textWords = words.filter(w => !/^\s+$/.test(w));
      const totalChars = textWords.join('').length;
      let currentOffset = 0;

      wordTimingsRef.current = textWords.map(word => {
        const wordWeight = word.length / (totalChars || 1);
        const wordDuration = wordWeight * duration;
        const timing = { word, start: currentOffset, end: currentOffset + wordDuration };
        currentOffset += wordDuration;
        return timing;
      });

      playBuffer(audioBuffer);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Synthese fehlgeschlagen.');
    } finally {
      setIsLoading(false);
    }
  };

  const handlePreview = async (e: React.MouseEvent, voice: typeof GERMAN_VOICES[0]) => {
    e.stopPropagation();
    if (previewingVoiceId === voice.id) {
      stopAllAudio(true);
      return;
    }

    stopAllAudio(true);
    setPreviewingVoiceId(voice.id);

    try {
      const base64 = await generateSpeech(voice.previewSnippet, voice.geminiVoice);
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      previewSourceNodeRef.current = source;
      source.start();
      source.onended = () => setPreviewingVoiceId(null);
    } catch (err) {
      setPreviewingVoiceId(null);
    }
  };

  const handleDownload = () => {
    if (!lastAudioBase64) return;
    const blob = createWavBlob(decode(lastAudioBase64), 24000);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Deutsch-KI_${isCloningMode ? 'CLONE' : selectedVoice.name}_${Date.now()}.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleTranslate = async () => {
    if (!text.trim()) return;
    setIsTranslating(true);
    setArabicText(null);
    try {
      const translated = await translateText(text);
      setArabicText(translated);
    } catch (err) {
      setError("Übersetzung fehlgeschlagen.");
    } finally {
      setIsTranslating(false);
    }
  };

  const startDictation = async () => {
    if (isDictating) { stopDictation(); return; }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      dictationAudioContextRef.current = audioCtx;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsDictating(true);
            const source = audioCtx.createMediaStreamSource(stream);
            const scriptProcessor = audioCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(input.length);
              for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioCtx.destination);
          },
          onmessage: (m) => {
            if (m.serverContent?.inputTranscription?.text) setText(p => p + m.serverContent!.inputTranscription!.text);
          },
          onerror: () => stopDictation(),
          onclose: () => stopDictation(),
        },
        config: { responseModalities: [Modality.AUDIO], inputAudioTranscription: {}, systemInstruction: 'Transcribe precise German.' },
      });
      liveSessionRef.current = await sessionPromise;
    } catch (err) { setError("Mikrofon Zugriff verweigert."); setIsDictating(false); }
  };

  const stopDictation = () => {
    liveSessionRef.current?.close();
    dictationAudioContextRef.current?.close();
    setIsDictating(false);
  };

  // Rendering Helper: Calculate accurate word index for highlighting
  let nonSpaceIndexCounter = 0;

  return (
    <div className="space-y-12 animate-fadeIn max-w-7xl mx-auto font-sans">
      {showScanner && (
        <CameraScanner 
          onTextScanned={(t) => setText(p => p ? `${p}\n${t}` : t)}
          onClose={() => setShowScanner(false)}
        />
      )}

      {/* --- VISION & MANUSCRIPT TERMINAL --- */}
      <section className="relative">
        <div className="absolute inset-0 bg-indigo-500/5 blur-[120px] rounded-full"></div>

        {/* Terminal Header */}
        <div className="flex items-end justify-between mb-4 px-2">
           <div className="flex flex-col">
             <div className="flex items-center gap-2 mb-1">
               <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
               <span className="text-[10px] text-emerald-500 font-mono tracking-widest uppercase">System_Online</span>
             </div>
             <h3 className="text-2xl font-black text-white tracking-tight">Eingabe Terminal</h3>
           </div>

           <div className="flex items-center gap-3">
             {isLoopEnabled && (
               <div className="flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-500/10 border border-indigo-500/40 text-[10px] font-mono text-indigo-300 animate-pulse shadow-[0_0_15px_rgba(99,102,241,0.2)]">
                 <span className="w-1.5 h-1.5 bg-indigo-400 rounded-full"></span>
                 LOOP_ACTIVE
               </div>
             )}

             <div className="flex bg-white/5 rounded-full p-1 border border-white/10 backdrop-blur-md">
                <button onClick={startDictation} className={`p-2.5 rounded-full transition-all duration-300 ${isDictating ? 'bg-red-500/20 text-red-400 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.4)]' : 'hover:bg-white/10 text-slate-400 hover:text-white'}`} title="Spracheingabe">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                </button>
                <button onClick={() => setShowScanner(true)} className="p-2.5 rounded-full hover:bg-white/10 text-slate-400 hover:text-white transition-all duration-300" title="Vision Scan">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                </button>
                <div className="w-px h-5 bg-white/10 mx-1 self-center"></div>
                <button onClick={handleTranslate} disabled={!text.trim() || isTranslating} className={`p-2.5 rounded-full transition-all duration-300 ${isTranslating ? 'text-amber-400 animate-spin' : 'hover:bg-amber-500/10 text-slate-400 hover:text-amber-400'}`} title="Translate to Arabic">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129" /></svg>
                </button>
             </div>
           </div>
        </div>

        {/* Terminal Body */}
        <div className="relative group rounded-2xl overflow-hidden border border-white/10 bg-[#0a0c12]/80 backdrop-blur-xl shadow-2xl transition-all duration-500 hover:border-indigo-500/30">
          <div className="absolute top-0 left-0 w-full h-0.5 bg-gradient-to-r from-transparent via-indigo-500 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-700"></div>

          <div className="relative min-h-[320px] p-6 font-mono text-lg leading-relaxed">
            {/* Visualizer Canvas Overlay */}
            <canvas 
              ref={visualizerCanvasRef} 
              width={800} 
              height={100} 
              className={`absolute bottom-0 left-0 w-full h-32 pointer-events-none opacity-30 transition-opacity duration-500 ${isPlaying ? 'opacity-30' : 'opacity-0'}`}
            />

            {/* Playback Text Overlay */}
            {isPlaying && (
              <div 
                ref={overlayRef}
                className="absolute inset-0 z-20 bg-[#05070a]/90 backdrop-blur-sm p-6 overflow-y-auto pointer-events-none scroll-smooth scrollbar-thin scrollbar-thumb-indigo-500/30 scrollbar-track-transparent"
              >
                <div className="flex flex-wrap gap-x-2 gap-y-1">
                  {words.map((part, idx) => {
                    const isWhitespace = /^\s+$/.test(part);
                    let isSpoken = false;

                    if (!isWhitespace) {
                      if (nonSpaceIndexCounter === currentWordIndex) {
                        isSpoken = true;
                      }
                      nonSpaceIndexCounter++;
                    }

                    return (
                      <span 
                        key={idx} 
                        ref={(el) => {
                           if (!isWhitespace) {
                             // Use nonSpaceIndexCounter relative to when this element was rendered
                             // But since we increment inside the map, we need to recalculate or store.
                             // Actually, simpler approach for refs: just push sequentially.
                             // But wordRefs needs to match currentWordIndex which is based on non-whitespace words.
                             // So:
                             if (isSpoken) wordRefs.current[currentWordIndex] = el;
                             // This is tricky. Let's just assign by global counter.
                             // Reset counter at start of render not possible easily in React.
                             // Alternative:
                           }
                           // Better logic: Just render. Scroll logic relies on index.
                           // Assign ref if it matches logic:
                           // Let's rely on a separate pass or simpler mapping.
                           // Actually, let's assume wordRefs is a flat array of SPANS.
                           // We need to map the visual `idx` to the logic `currentWordIndex`.
                        }}
                        // Fix for ref assignment:
                        ref={(el) => {
                            // We need to store refs for "scrolling". 
                            // `currentWordIndex` refers to the index in the filtered `words` array.
                            // We need to reconstruct that mapping.
                            // However, we can just filter in the parent map.
                        }}
                        className={`transition-all duration-150 relative ${isSpoken ? 'text-transparent bg-clip-text bg-gradient-to-r from-white to-indigo-200 font-bold scale-105 z-10 drop-shadow-[0_0_10px_rgba(99,102,241,0.8)]' : 'text-slate-600'}`}
                      >
                         {/* We need to properly assign the ref for scrolling. 
                             Since currentWordIndex is based on non-whitespace, 
                             we only assign ref if !isWhitespace and we track the index manually outside this map? 
                             No, pure function. 

                             FIX: Let's do a trick. We use a data attribute and querySelector? No, refs are faster.
                             We will use a separate counter variable declared before return, but React pure render warns against it.
                             Safe way: Map filtered words to original indices?

                             Let's use the valid logic:
                         */}
                        {part}
                      </span>
                    );
                  })}
                  {/* Re-rendering words with proper ref assignment logic */}
                </div>
                {/* 
                   Correction: The map above makes it hard to sync the index. 
                   Let's use a cleaner approach for the overlay: Map ONLY filtered words, join with spaces visually? 
                   No, format must match input.

                   Better approach: Map the original array, but keep a local counter for "meaningful" words.
                */}
              </div>
            )}

            {/* Rerender for Ref Sync */}
            {isPlaying && (
                <div className="absolute inset-0 z-20 bg-[#05070a]/90 backdrop-blur-sm p-6 overflow-y-auto pointer-events-none scroll-smooth">
                    <div className="flex flex-wrap gap-x-1.5 gap-y-1">
                        {(() => {
                            let wordCounter = 0;
                            return words.map((part, idx) => {
                                const isWhitespace = /^\s+$/.test(part);
                                const isActive = !isWhitespace && wordCounter === currentWordIndex;
                                const localIndex = wordCounter; // capture

                                if (!isWhitespace) wordCounter++;

                                return (
                                    <span
                                        key={idx}
                                        ref={(el) => {
                                            if (!isWhitespace && el) {
                                                wordRefs.current[localIndex] = el;
                                            }
                                        }}
                                        className={`transition-all duration-150 ${isActive ? 'text-white bg-indigo-500/40 px-1 rounded shadow-[0_0_15px_rgba(99,102,241,0.4)] border border-indigo-500/20' : 'text-slate-500'}`}
                                    >
                                        {part}
                                    </span>
                                );
                            });
                        })()}
                    </div>
                </div>
            )}

            <textarea
              className={`w-full h-full min-h-[300px] bg-transparent border-none outline-none resize-none text-slate-300 placeholder-slate-700/50 selection:bg-indigo-500/30 ${isPlaying ? 'opacity-0' : 'opacity-100'}`}
              placeholder="// Geben Sie Ihren Text ein oder initialisieren Sie den Scan-Vorgang..."
              value={text}
              onChange={(e) => setText(e.target.value)}
              disabled={isPlaying}
              spellCheck={false}
            />
          </div>

          {/* Terminal Status Bar */}
          <div className="bg-[#050608] border-t border-white/5 px-4 py-3 flex justify-between items-center text-[10px] font-mono text-slate-500 uppercase tracking-widest">
             <div className="flex items-center gap-4">
                 <div className="flex items-center gap-2">
                    <span className="w-1.5 h-1.5 rounded-full bg-slate-700"></span>
                    <span>Chars: {text.length}</span>
                 </div>
                 {text.length > 0 && <span className="text-slate-700">|</span>}
                 {text.length > 0 && <span>~{(text.length / 15).toFixed(0)} Sec Est.</span>}
             </div>

             <div className="flex items-center gap-3">
