          <svg className="w-6 h-6 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          <span className="text-sm font-mono tracking-wide">{error}</span>
        </div>
      )}

      {/* --- NEURAL VOICE CLONING LAB --- */}
      <section className="border-b border-white/5 pb-10">
         <div className="flex items-center justify-between mb-8 px-2">
            <div>
              <h3 className="text-xl font-bold text-white tracking-tight flex items-center gap-3">
                 Neural Voice Lab
                 <span className="text-[9px] bg-gradient-to-r from-indigo-500 to-purple-500 text-white px-2 py-0.5 rounded shadow-lg uppercase tracking-widest">Beta Access</span>
              </h3>
              <p className="text-[10px] text-slate-500 font-mono uppercase tracking-widest mt-2">Advanced Prompt Engineering & Style Transfer</p>
            </div>

            <button 
              onClick={() => setIsCloningMode(!isCloningMode)}
              className={`relative px-5 py-2.5 rounded-xl border transition-all duration-300 flex items-center gap-3 ${isCloningMode ? 'bg-indigo-600 border-indigo-400 text-white shadow-[0_0_25px_rgba(99,102,241,0.4)]' : 'bg-white/5 border-white/10 text-slate-400 hover:border-white/30 hover:bg-white/10'}`}
            >
              <div className={`w-2 h-2 rounded-full ${isCloningMode ? 'bg-white animate-pulse' : 'bg-slate-500'}`}></div>
              <span className="text-xs font-bold tracking-widest uppercase">{isCloningMode ? 'Engine Active' : 'Activate Cloning'}</span>
            </button>
         </div>

         <div className={`transition-all duration-700 overflow-hidden ${isCloningMode ? 'max-h-[800px] opacity-100 translate-y-0' : 'max-h-0 opacity-0 -translate-y-4'}`}>
