// --- Custom Control Knob Component ---
const ControlKnob: React.FC<{ value: number; onChange: (val: number) => void; label?: string; color?: string }> = ({ value, onChange, label, color = "white" }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startYRef = useRef<number>(0);
  const startValueRef = useRef<number>(0);

  const getClientY = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent): number => {
    return 'touches' in e ? (e as any).touches[0].clientY : (e as any).clientY;
  };

  const handleStart = (e: React.MouseEvent | React.TouchEvent) => {
    setIsDragging(true);
    const clientY = getClientY(e);
    startYRef.current = clientY;
    startValueRef.current = value;
    document.body.style.userSelect = 'none';
  };

  useEffect(() => {
    const handleMove = (e: MouseEvent | TouchEvent) => {
      if (!isDragging) return;
      if (e.cancelable) e.preventDefault();

      const clientY = getClientY(e);
      const deltaY = startYRef.current - clientY;
      const change = deltaY / 150; 
      let newValue = startValueRef.current + change;
      newValue = Math.max(0, Math.min(1, newValue));
      onChange(newValue);
    };

    const handleEnd = () => {
      setIsDragging(false);
      document.body.style.userSelect = '';
    };

    if (isDragging) {
      window.addEventListener('mousemove', handleMove, { passive: false });
      window.addEventListener('touchmove', handleMove, { passive: false });
      window.addEventListener('mouseup', handleEnd);
      window.addEventListener('touchend', handleEnd);
    }

    return () => {
      window.removeEventListener('mousemove', handleMove);
      window.removeEventListener('touchmove', handleMove);
      window.removeEventListener('mouseup', handleEnd);
      window.removeEventListener('touchend', handleEnd);
    };
  }, [isDragging, onChange]);

  // Generate ticks
  const ticks = [];
  const numTicks = 20; 
  const startAngle = 135;
  const endAngle = 405;

  for (let i = 0; i < numTicks; i++) {
    const pct = i / (numTicks - 1);
    const angle = startAngle + (endAngle - startAngle) * pct;
    const rad = (angle * Math.PI) / 180;
    const isLit = value >= pct;

    const innerR = 32;
    const outerR = 42;
    const x1 = 50 + innerR * Math.cos(rad);
    const y1 = 50 + innerR * Math.sin(rad);
    const x2 = 50 + outerR * Math.cos(rad);
    const y2 = 50 + outerR * Math.sin(rad);

    ticks.push(
      <line 
        key={i}
        x1={x1} y1={y1} x2={x2} y2={y2}
        stroke={isLit ? color : "#334155"}
        strokeWidth={2}
        strokeLinecap="round"
        className={`transition-colors duration-100 ${isLit ? 'opacity-100' : 'opacity-30'}`}
      />
    );
  }

  const knobAngle = startAngle + (endAngle - startAngle) * value;
  const knobRad = (knobAngle * Math.PI) / 180;
  const dotR = 18;
  const dotX = 50 + dotR * Math.cos(knobRad);
  const dotY = 50 + dotR * Math.sin(knobRad);

  return (
    <div 
      className="relative w-12 h-12 flex flex-col items-center justify-center cursor-ns-resize group select-none"
      style={{ touchAction: 'none' }}
      onMouseDown={handleStart}
      onTouchStart={handleStart}
      title={label}
    >
      <svg width="48" height="48" viewBox="0 0 100 100">
        {ticks}
        <circle cx="50" cy="50" r="26" fill="black" opacity="0.5" filter="blur(2px)" />
        <circle 
          cx="50" cy="50" r="25" 
          fill="url(#knobGradient)" 
          stroke="#1e293b" 
          strokeWidth="1"
          className="drop-shadow-lg"
        />
        <defs>
          <linearGradient id="knobGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#334155" />
            <stop offset="100%" stopColor="#0f172a" />
          </linearGradient>
        </defs>
        <circle 
          cx={dotX} cy={dotY} r="3" 
          fill={value > 0 ? color : "#64748b"} 
          className={value > 0 ? "drop-shadow-[0_0_4px_rgba(255,255,255,0.8)]" : ""}
        />
      </svg>
      {label && <div className="absolute -bottom-4 text-[7px] font-mono font-bold text-slate-500 uppercase tracking-wider">{label}</div>}
    </div>
  );
};


export const VoiceStudio: React.FC = () => {
