import { GoogleGenAI, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Generates high-quality German speech from text.
 * Uses advanced prompt engineering to enforce a professional persona.
 */
export const generateSpeech = async (text: string, voiceName: string, cloningPersona?: string) => {
  const ai = getAI();

  let finalPrompt = "";

  if (cloningPersona) {
    // Neural Cloning Mode: Explicitly define the persona and acting style
    finalPrompt = `
      [System Instruction: You are a professional German voice actor performing a high-fidelity studio recording.]
      [Persona: ${cloningPersona}]
      [Task: Read the following text naturally in German. Maintain consistent character and high audio quality.]

      Text to read: "${text}"
    `;
  } else {
    // Standard High-Fidelity Mode: Use the extended persona from constants if available (passed as cloningPersona usually, but here we assume voiceName linkage in UI)
    // However, for standard generation without cloningPersona param, we just ensure native quality.
    finalPrompt = `
      [System Instruction: Act as a professional German narrator. Speak with perfect pronunciation, natural pacing, and high-fidelity studio quality.]

      Bitte lies diesen Text auf Deutsch vor: "${text}"
    `;
  }

  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: finalPrompt }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audiogenerierung fehlgeschlagen. Keine Daten empfangen.");
  return base64Audio;
};

/**
 * Extracts text from an image using Gemini vision capabilities.
 */
export const extractTextFromImage = async (base64Image: string) => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: "image/jpeg",
            data: base64Image,
          },
        },
        { text: "Extrahiere den gesamten Text aus diesem Bild. Gib nur den erkannten Text zurück ohne zusätzliche Kommentare." },
      ],
    },
  });

  return response.text || "";
};

/**
 * Translates text from German to Arabic.
 */
export const translateText = async (text: string): Promise<string> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: [{ parts: [{ text: `Translate the following German text into Arabic. Return strictly only the translated Arabic text, no markdown, no explanations.\n\nText: ${text}` }] }],
  });
  return response.text?.trim() || "";
};

