import { GoogleGenAI, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Helper to execute API calls with exponential backoff for 429 errors.
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 3): Promise<T> {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (error: any) {
      const isQuotaError = 
        error.message?.includes('429') || 
        error.status === 429 || 
        error.toString().includes('Resource has been exhausted') ||
        error.toString().includes('429');

      if (isQuotaError && attempt < maxRetries) {
        attempt++;
        const delay = Math.pow(2, attempt) * 1000 + (Math.random() * 500); // 2s, 4s, 8s + jitter
        console.warn(`API Quota 429 hit. Retrying in ${Math.round(delay)}ms... (Attempt ${attempt})`);
        await wait(delay);
        continue;
      }

      if (isQuotaError) {
        throw new Error("Server-Auslastung hoch (429). Bitte warten Sie einige Sekunden vor der nächsten Anfrage.");
      }
      throw error;
    }
  }
}

