import { GoogleGenAI, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Helper to execute API calls with exponential backoff for 429/503 errors.
 * Includes Jitter to prevent thundering herd.
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 3, operationName = "API Call"): Promise<T> {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (error: any) {
      const msg = error.message || error.toString();
      const isQuotaError = 
        msg.includes('429') || 
        error.status === 429 || 
        msg.includes('Resource has been exhausted') ||
        msg.includes('Too Many Requests');

      const isServerError = error.status === 503 || msg.includes('503');

      if ((isQuotaError || isServerError) && attempt < maxRetries) {
        attempt++;
        // Base delay: 2s, 4s, 8s
        // Jitter: +0 to 1000ms to avoid synchronized retries
        const delay = Math.pow(2, attempt) * 1000 + (Math.random() * 1000); 
        console.warn(`[${operationName}] Warning: ${isQuotaError ? 'Quota (429)' : 'Server (503)'}. Retrying in ${Math.round(delay)}ms... (Attempt ${attempt}/${maxRetries})`);
        await wait(delay);
        continue;
      }

      if (isQuotaError) {
        console.error(`[${operationName}] Failed after ${attempt} retries due to Quota.`);
        throw new Error("⚠️ Server-Überlastung (429). Das System ist momentan stark ausgelastet. Bitte warten Sie 10-15 Sekunden.");
      }

      console.error(`[${operationName}] Critical Failure:`, error);
      throw error;
    }
  }
}

