  const [isLoading, setIsLoading] = useState(false);
  const [isTranslating, setIsTranslating] = useState(false);
  const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isDictating, setIsDictating] = useState(false);
  const [isLoopEnabled, setIsLoopEnabled] = useState(false);
  const [showScanner, setShowScanner] = useState(false);
  const [lastAudioBase64, setLastAudioBase64] = useState<string | null>(null);
  const [currentWordIndex, setCurrentWordIndex] = useState(-1);
  const [downloadQuality, setDownloadQuality] = useState<number>(24000); 

  // Audio Controls
  const [volume, setVolume] = useState(0.85);
  const [reverbLevel, setReverbLevel] = useState(0.0);
  const [delayLevel, setDelayLevel] = useState(0.0);
  const [freshAirLevel, setFreshAirLevel] = useState(0.0); // High Shelf

  const [showControls, setShowControls] = useState(true);
  const [favorites, setFavorites] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('deutsch-ki-favorites');
      return saved ? JSON.parse(saved) : [];
    } catch { return []; }
  });

  // Audio Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const dictationAudioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  // Audio Nodes Refs for Realtime Updates
  const gainNodeRef = useRef<GainNode | null>(null); 
  const reverbGainRef = useRef<GainNode | null>(null); 
  const delayGainRef = useRef<GainNode | null>(null); 
  const freshAirFilterRef = useRef<BiquadFilterNode | null>(null); 
  const impulseBufferRef = useRef<AudioBuffer | null>(null); 

  const previewSourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const currentAudioBufferRef = useRef<AudioBuffer | null>(null);
  const startTimeRef = useRef<number>(0);
  const wordTimingsRef = useRef<WordTiming[]>([]);
  const animationFrameRef = useRef<number>(0);
  const liveSessionRef = useRef<any>(null);

  // Refs for UI and State
  const overlayRef = useRef<HTMLDivElement>(null);
  const wordRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const visualizerCanvasRef = useRef<HTMLCanvasElement>(null);

  const isLoopEnabledRef = useRef(isLoopEnabled);
  const isPlayingRef = useRef(isPlaying);

  const volumeRef = useRef(volume);
  const reverbLevelRef = useRef(reverbLevel);
  const delayLevelRef = useRef(delayLevel);
  const freshAirLevelRef = useRef(freshAirLevel);

  // Sync refs
  useEffect(() => { isLoopEnabledRef.current = isLoopEnabled; }, [isLoopEnabled]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { volumeRef.current = volume; }, [volume]);
  useEffect(() => { reverbLevelRef.current = reverbLevel; }, [reverbLevel]);
  useEffect(() => { delayLevelRef.current = delayLevel; }, [delayLevel]);
  useEffect(() => { freshAirLevelRef.current = freshAirLevel; }, [freshAirLevel]);

  useEffect(() => { localStorage.setItem('deutsch-ki-favorites', JSON.stringify(favorites)); }, [favorites]);

  // --- REALTIME AUDIO UPDATES ---
  useEffect(() => {
    const ctx = audioContextRef.current;
    if (ctx && ctx.state === 'running') {
       const now = ctx.currentTime;
       if (gainNodeRef.current) gainNodeRef.current.gain.setTargetAtTime(volume, now, 0.05);
       if (reverbGainRef.current) reverbGainRef.current.gain.setTargetAtTime(reverbLevel, now, 0.05);
       if (delayGainRef.current) delayGainRef.current.gain.setTargetAtTime(delayLevel, now, 0.05);
       // Cap Air boost at 12dB
       if (freshAirFilterRef.current) freshAirFilterRef.current.gain.setTargetAtTime(freshAirLevel * 12, now, 0.05);
    }
  }, [volume, reverbLevel, delayLevel, freshAirLevel]);

  // Create Impulse Response for Reverb
  const getImpulseBuffer = (ctx: AudioContext) => {
    if (impulseBufferRef.current) return impulseBufferRef.current;

    // Create a high-quality synthetic reverb (noise with exponential decay)
    const rate = ctx.sampleRate;
    const length = rate * 2.5; // 2.5s tail
    const decay = 3.0;
    const impulse = ctx.createBuffer(2, length, rate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = i / length;
        // Pink noise approximation for warmer reverb
        const white = (Math.random() * 2 - 1);
        const envelope = Math.pow(1 - n, decay);
        left[i] = white * envelope;
        right[i] = white * envelope; // Stereo correlation can be adjusted here
    }
    impulseBufferRef.current = impulse;
    return impulse;
  };

  useEffect(() => { wordRefs.current = []; }, [text]);

  // Auto-scroll effect
  useEffect(() => {
    if (isPlaying && currentWordIndex >= 0 && wordRefs.current[currentWordIndex]) {
      wordRefs.current[currentWordIndex]?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
        inline: 'nearest'
      });
    }
  }, [currentWordIndex, isPlaying]);

  // Cleanup
  useEffect(() => {
    return () => {
      stopAllAudio(true);
      if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close().catch(() => {});
      }
      if (dictationAudioContextRef.current && dictationAudioContextRef.current.state !== 'closed') {
        dictationAudioContextRef.current.close().catch(() => {});
      }
      if (liveSessionRef.current) {
        Promise.resolve(liveSessionRef.current).then(session => {
          try { session?.close(); } catch {}
        });
      }
      if ('mediaSession' in navigator) {
        navigator.mediaSession.metadata = null;
        navigator.mediaSession.playbackState = 'none';
      }
    };
  }, []);

  const words = useMemo(() => text.split(/(\s+)/), [text]);
  const favoriteVoices = useMemo(() => GERMAN_VOICES.filter(v => favorites.includes(v.id)), [favorites, GERMAN_VOICES]);

  const toggleFavorite = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setFavorites(prev => prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]);
  };

  const stopAllAudio = useCallback((manual: boolean = true) => {
    if (manual) isPlayingRef.current = false;

    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); } catch (e) {}
      try { sourceNodeRef.current.disconnect(); } catch (e) {}
      sourceNodeRef.current = null;
    }

    if (previewSourceNodeRef.current) {
      try { previewSourceNodeRef.current.stop(); } catch (e) {}
      try { previewSourceNodeRef.current.disconnect(); } catch (e) {}
      previewSourceNodeRef.current = null;
    }
    cancelAnimationFrame(animationFrameRef.current);

    if (manual) {
      setIsPlaying(false);
      setCurrentWordIndex(-1);
      if (visualizerCanvasRef.current) {
        const ctx = visualizerCanvasRef.current.getContext('2d');
        if (ctx) ctx.clearRect(0, 0, visualizerCanvasRef.current.width, visualizerCanvasRef.current.height);
      }
      if ('mediaSession' in navigator) {
        navigator.mediaSession.playbackState = 'paused';
      }
    }
    setPreviewingVoiceId(null);
  }, []);

  const getAudioContext = () => {
    if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
      // 48kHz for Studio Quality
      const AudioCtor = (window.AudioContext || (window as any).webkitAudioContext);
      audioContextRef.current = new AudioCtor({ sampleRate: 48000 });
    }
    return audioContextRef.current;
  };

  const drawVisualizer = () => {
    if (!analyserRef.current || !visualizerCanvasRef.current) return;

    const canvas = visualizerCanvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bufferLength = analyserRef.current.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    analyserRef.current.getByteFrequencyData(dataArray);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const barWidth = (canvas.width / bufferLength) * 2.5;
    let barHeight;
    let x = 0;

    const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
    gradient.addColorStop(0, '#818cf8'); 
    gradient.addColorStop(1, '#22d3ee'); 

    ctx.fillStyle = gradient;

    for (let i = 0; i < bufferLength; i++) {
      barHeight = dataArray[i] / 2;
      ctx.fillRect(x, canvas.height - barHeight, barWidth, barHeight);
      x += barWidth + 1;
    }
  };

  // --- AUDIO ENGINE ---
  const playBuffer = useCallback((buffer: AudioBuffer) => {
    const ctx = getAudioContext();
    if (ctx.state === 'suspended') ctx.resume();

    stopAllAudio(false);

    const source = ctx.createBufferSource();
    source.buffer = buffer;

    // --- NODES CREATION ---

    // 1. Fresh Air (High Shelf EQ)
    const freshAirFilter = ctx.createBiquadFilter();
    freshAirFilter.type = 'highshelf';
    freshAirFilter.frequency.value = 12000; 
    freshAirFilter.gain.value = freshAirLevelRef.current * 12; // Initial Value
    freshAirFilterRef.current = freshAirFilter;

    // 2. Dynamics Compressor (Soft Clipper / Limiter)
    // Optimized for voice: Fast attack, moderate release
    const compressor = ctx.createDynamicsCompressor();
    compressor.threshold.value = -12;
    compressor.knee.value = 30;
    compressor.ratio.value = 12;
    compressor.attack.value = 0.003;
    compressor.release.value = 0.25;

    // 3. Master Volume
    const masterGain = ctx.createGain();
    masterGain.gain.value = volumeRef.current;
    gainNodeRef.current = masterGain;

    // 4. Analyzer
    const analyser = ctx.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    // 5. FX Sends
    const reverbGain = ctx.createGain();
    reverbGain.gain.value = reverbLevelRef.current;
    reverbGainRef.current = reverbGain;
    const convolver = ctx.createConvolver();
    convolver.buffer = getImpulseBuffer(ctx);

    const delayNode = ctx.createDelay();
    delayNode.delayTime.value = 0.35;
    const delayFeedback = ctx.createGain();
    delayFeedback.gain.value = 0.3; // Lower feedback for cleaner vocal
    const delayOutputGain = ctx.createGain();
    delayOutputGain.gain.value = delayLevelRef.current;
    delayGainRef.current = delayOutputGain;

    // --- GRAPH ROUTING ---
    // Source -> Air -> Compressor -> Master
    source.connect(freshAirFilter);
    freshAirFilter.connect(compressor);

    // FX Routing (Parallel processing from Air output)
    freshAirFilter.connect(convolver);
    convolver.connect(reverbGain);
    reverbGain.connect(compressor); // FX mix back before compressor to glue it together

    freshAirFilter.connect(delayNode);
    delayNode.connect(delayFeedback);
    delayFeedback.connect(delayNode);
    delayNode.connect(delayOutputGain);
    delayOutputGain.connect(compressor); // FX mix back before compressor

    // Output Stage
    compressor.connect(masterGain);
    masterGain.connect(analyser);
    analyser.connect(ctx.destination);

    // Store Refs
    sourceNodeRef.current = source;
    analyserRef.current = analyser;
    startTimeRef.current = ctx.currentTime;

    setIsPlaying(true);
    setCurrentWordIndex(-1);
    isPlayingRef.current = true;

    if ('mediaSession' in navigator) {
      navigator.mediaSession.metadata = new MediaMetadata({
        title: isCloningMode ? 'Voice Clone Audio' : `Deutsch-KI: ${selectedVoice.name}`,
        artist: 'Deutsch-KI Super App',
        album: 'Neural Synthesis',
        artwork: [
          { src: 'https://cdn-icons-png.flaticon.com/512/8804/8804369.png', sizes: '512x512', type: 'image/png' }
        ]
      });
      navigator.mediaSession.playbackState = 'playing';
      navigator.mediaSession.setActionHandler('pause', () => stopAllAudio(true));
      navigator.mediaSession.setActionHandler('stop', () => stopAllAudio(true));
    }

    const tick = () => {
      if (!ctx || !isPlayingRef.current) return;
      const elapsed = ctx.currentTime - startTimeRef.current;
      const timings = wordTimingsRef.current;

      let foundIndex = -1;
      for (let i = 0; i < timings.length; i++) {
        if (elapsed >= timings[i].start && elapsed <= timings[i].end) {
          foundIndex = i;
          break;
        }
      }
      setCurrentWordIndex(foundIndex);
      drawVisualizer();

      // Extended tail for Reverb/Delay
      if (elapsed < buffer.duration + 0.5 + (reverbLevelRef.current > 0 ? 3.0 : 0.5)) { 
        animationFrameRef.current = requestAnimationFrame(tick);
      } else {
        if (visualizerCanvasRef.current) {
          const c = visualizerCanvasRef.current.getContext('2d');
          c?.clearRect(0, 0, visualizerCanvasRef.current.width, visualizerCanvasRef.current.height);
        }
      }
    };
    animationFrameRef.current = requestAnimationFrame(tick);

    source.start();

    source.onended = () => {
      if (isLoopEnabledRef.current && isPlayingRef.current) {
        playBuffer(buffer);
      } else {
        setIsPlaying(false);
        setCurrentWordIndex(-1);
        if ('mediaSession' in navigator) {
            navigator.mediaSession.playbackState = 'none';
        }
      }
    };
  }, [stopAllAudio, isCloningMode, selectedVoice.name]);

  const handleGenerate = async () => {
    if (!text.trim()) return;
    setIsLoading(true);
    setError(null);
    setLastAudioBase64(null);
    currentAudioBufferRef.current = null;
    stopAllAudio(true);

    const ctx = getAudioContext();
    if (ctx.state === 'suspended') await ctx.resume();

    try {
      const targetPersona = isCloningMode 
        ? (cloningPersona.trim() || 'Professional Narrator') 
        : selectedVoice.persona;

      const base64 = await generateSpeech(text, selectedVoice.geminiVoice, targetPersona);

      setLastAudioBase64(base64);

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      currentAudioBufferRef.current = audioBuffer;

      const duration = audioBuffer.duration;
      const textWords = words.filter(w => !/^\s+$/.test(w));
      const totalChars = textWords.join('').length;
      let currentOffset = 0;

      wordTimingsRef.current = textWords.map(word => {
        const wordWeight = word.length / (totalChars || 1);
        const wordDuration = wordWeight * duration;
        const timing = { word, start: currentOffset, end: currentOffset + wordDuration };
        currentOffset += wordDuration;
        return timing;
      });

      playBuffer(audioBuffer);
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Synthese fehlgeschlagen.');
    } finally {
      setIsLoading(false);
    }
  };

  const handlePreview = async (e: React.MouseEvent, voice: typeof GERMAN_VOICES[0]) => {
    e.stopPropagation();
    if (previewingVoiceId === voice.id) {
      stopAllAudio(true);
      return;
    }

    stopAllAudio(true);
    setPreviewingVoiceId(voice.id);

    try {
      const base64 = await generateSpeech(voice.previewSnippet, voice.geminiVoice, voice.persona);
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64), ctx, 24000, 1);
      const source = ctx.createBufferSource();

      // Simpler chain for preview
      const masterGain = ctx.createGain();
      masterGain.gain.value = volume;
      gainNodeRef.current = masterGain;

      source.buffer = audioBuffer;
      source.connect(masterGain);
      masterGain.connect(ctx.destination);

      previewSourceNodeRef.current = source;
      source.start();
      source.onended = () => setPreviewingVoiceId(null);
    } catch (err) {
      setPreviewingVoiceId(null);
    }
  };

  const sanitizeFilename = (name: string) => {
    return name.replace(/[^a-z0-9]/gi, '_').toLowerCase();
  };

  const handleDownload = () => {
    if (!currentAudioBufferRef.current) return;
    const blob = audioBufferToWav(currentAudioBufferRef.current, downloadQuality);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    const kbpsLabel = downloadQuality === 24000 ? '320kbps' : downloadQuality === 16000 ? '256kbps' : '128kbps';
    const voiceLabel = isCloningMode ? 'custom_clone' : sanitizeFilename(selectedVoice.name);
    a.download = `deutsch_ki_${voiceLabel}_${kbpsLabel}_${Date.now()}.wav`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleShare = async () => {
    if (!currentAudioBufferRef.current) return;
    try {
      const blob = audioBufferToWav(currentAudioBufferRef.current, downloadQuality);
      const voiceLabel = isCloningMode ? 'custom_clone' : sanitizeFilename(selectedVoice.name);
      const filename = `deutsch_ki_${voiceLabel}_${Date.now()}.wav`;
      const file = new File([blob], filename, { type: 'audio/wav' });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
            title: 'Deutsch-KI Audio',
            text: `Audio generiert mit Deutsch-KI (${selectedVoice.name})`,
            files: [file]
        });
      } else {
        handleDownload();
      }
    } catch (err) {
      setError("Teilen nicht möglich, Download gestartet.");
      handleDownload();
    }
  };

  const handleTranslate = async () => {
    if (arabicText) {
        setArabicText(null);
        return;
    }
    if (!text.trim()) return;
    setIsTranslating(true);
    setArabicText(null);
    try {
      const translated = await translateText(text);
      setArabicText(translated);
    } catch (err) {
      setError("Übersetzung fehlgeschlagen.");
    } finally {
      setIsTranslating(false);
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target?.result as string;
      if (content) {
        setText(prev => prev ? `${prev}\n${content}` : content);
      }
    };
    reader.readAsText(file);
    event.target.value = '';
  };

  const startDictation = async () => {
    if (isDictating) { stopDictation(); return; }
    if (dictationAudioContextRef.current && dictationAudioContextRef.current.state !== 'closed') {
      await dictationAudioContextRef.current.close().catch(() => {});
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      dictationAudioContextRef.current = audioCtx;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsDictating(true);
            const source = audioCtx.createMediaStreamSource(stream);
            const scriptProcessor = audioCtx.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(input.length);
              for (let i = 0; i < input.length; i++) int16[i] = input[i] * 32768;
              const pcmBlob = { data: encode(new Uint8Array(int16.buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioCtx.destination);
          },
          onmessage: (m) => {
            if (m.serverContent?.inputTranscription?.text) setText(p => p + m.serverContent!.inputTranscription!.text);
          },
          onerror: () => stopDictation(),
          onclose: () => stopDictation(),
        },
        config: { responseModalities: [Modality.AUDIO], inputAudioTranscription: {}, systemInstruction: 'Transcribe precise German.' },
      });
      liveSessionRef.current = sessionPromise;
      await sessionPromise;
    } catch (err) { setError("Mikrofon Zugriff verweigert."); setIsDictating(false); }
  };

  const stopDictation = () => {
    try { 
      Promise.resolve(liveSessionRef.current).then(session => session?.close()); 
    } catch {}
    if (dictationAudioContextRef.current && dictationAudioContextRef.current.state !== 'closed') {
      dictationAudioContextRef.current.close().catch(() => {});
    }
    setIsDictating(false);
  };

  return (
    <div className="space-y-12 animate-fadeIn max-w-7xl mx-auto font-sans">
      <style>{`
        @keyframes ghostFloat {
          0%, 100% { transform: translateY(0px); box-shadow: 0 5px 15px rgba(99,102,241,0.2); }
          50% { transform: translateY(-6px); box-shadow: 0 15px 25px rgba(99,102,241,0.4); }
        }
        .ghost-float {
          animation: ghostFloat 3s ease-in-out infinite;
        }
        /* Hide scrollbar for Chrome, Safari and Opera */
        .scrollbar-none::-webkit-scrollbar {
            display: none;
        }
        /* Hide scrollbar for IE, Edge and Firefox */
        .scrollbar-none {
            -ms-overflow-style: none;  /* IE and Edge */
            scrollbar-width: none;  /* Firefox */
        }
      `}</style>

      {showScanner && (
        <CameraScanner 
          onTextScanned={(t) => setText(p => p ? `${p}\n${t}` : t)}
          onClose={() => setShowScanner(false)}
        />
      )}

      {/* --- VISION & MANUSCRIPT TERMINAL --- */}
      <section className="relative">
        <div className="absolute inset-0 bg-indigo-500/5 blur-[120px] rounded-full"></div>

        {/* MINIMIZED TOOLBAR */}
        <div className={`transition-all duration-500 ease-in-out overflow-hidden ${showControls ? 'max-h-40 opacity-100 mb-4' : 'max-h-0 opacity-0 mb-0'}`}>
          <div className="bg-[#0f1115]/90 border border-white/10 rounded-xl p-1.5 shadow-lg relative z-20 backdrop-blur-md">

             {/* Scrollable Container for Mobile */}
             <div className="flex items-center justify-between gap-2 overflow-x-auto scrollbar-none pb-1 sm:pb-0">

                 {/* Left Action Group (Inputs) */}
                 <div className="flex items-center gap-1 flex-shrink-0">
                    {/* Dictation Button */}
                    <button 
                        onClick={startDictation} 
                        className={`
                            w-10 h-10 rounded-lg flex items-center justify-center transition-all duration-300 relative
                            ${isDictating 
                                ? 'bg-red-500/20 text-red-400 border border-red-500/30' 
                                : 'hover:bg-white/5 text-slate-400 hover:text-white border border-transparent'}
                        `}
                        title="Spracheingabe"
                    >
                        {isDictating && <span className="absolute top-2 right-2 w-1.5 h-1.5 bg-red-500 rounded-full animate-pulse"></span>}
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                    </button>

                    {/* Vision Scanner Button */}
                    <button 
                        onClick={() => setShowScanner(true)} 
                        className="w-10 h-10 rounded-lg flex items-center justify-center hover:bg-white/5 text-slate-400 hover:text-white transition-all border border-transparent hover:border-white/5"
                        title="Vision Scan"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                    </button>

                    {/* Translate Button */}
                    <button 
                        onClick={handleTranslate}
                        disabled={isTranslating}
                        className={`
                            w-10 h-10 rounded-lg flex items-center justify-center transition-all duration-300 relative
                            ${arabicText 
                                ? 'bg-amber-500/20 text-amber-400 border border-amber-500/30' 
                                : 'hover:bg-white/5 text-slate-400 hover:text-white border border-transparent'}
                        `}
                        title="Translate to Arabic"
                    >
                        <svg className={`w-5 h-5 ${isTranslating ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            {isTranslating ? (
