const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Helper to execute API calls with exponential backoff for 429/503 errors.
 * Includes Jitter to prevent thundering herd.
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 5, operationName = "API Call"): Promise<T> {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (error: any) {
      const msg = error.message || error.toString();
      const isQuotaError = 
        msg.includes('429') || 
        error.status === 429 || 
        msg.includes('Resource has been exhausted') || 
        msg.includes('Too Many Requests');

      const isServerError = error.status === 503 || msg.includes('503') || msg.includes('overloaded');

      if ((isQuotaError || isServerError) && attempt < maxRetries) {
        attempt++;

        // Exponential backoff strategy
        // Quota (429): Start higher (4s) to clear rate limit windows
        // Server (503): Start lower (2s)
        let baseDelay = isQuotaError ? 4000 : 2000;

        // Calculate delay: base * 2^(attempt-1) + jitter (0-1500ms)
        // Attempt 1 (Quota): ~4-5.5s
        // Attempt 2 (Quota): ~8-9.5s
        // Attempt 3 (Quota): ~16-17.5s
        // Attempt 4 (Quota): ~32-33.5s
        // Attempt 5 (Quota): ~64-65.5s
        const delay = (baseDelay * Math.pow(2, attempt - 1)) + (Math.random() * 1500);

        console.warn(`[${operationName}] Warning: ${isQuotaError ? 'Quota (429)' : 'Server (503)'}. Retrying in ${Math.round(delay)}ms... (Attempt ${attempt}/${maxRetries})`);

        await wait(delay);
        continue;
      }

      if (isQuotaError) {
        console.error(`[${operationName}] Failed after ${attempt} retries due to Quota.`);
        throw new Error("⚠️ Server-Limit erreicht (429). Die KI ist momentan stark ausgelastet. Bitte warten Sie 30-60 Sekunden und versuchen Sie es erneut.");
      }

      console.error(`[${operationName}] Critical Failure:`, error);
      throw error;
    }
  }
}

