import { GoogleGenAI, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Helper to execute API calls with exponential backoff for 429/503 errors.
 * Includes Jitter to prevent thundering herd.
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 5, operationName = "API Call"): Promise<T> {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (error: any) {
      // Normalize error message
      const msg = (error.message || error.toString()).toLowerCase();
      const status = error.status || error.code || 0;

      // Detect Quota/Rate Limit Errors
      const isQuotaError = 
        msg.includes('429') || 
        status === 429 || 
        msg.includes('resource has been exhausted') || 
        msg.includes('too many requests') ||
        msg.includes('quota');

      // Detect Server Overload/Availability Errors
      const isServerError = 
        status === 503 || 
        msg.includes('503') || 
        msg.includes('overloaded') ||
        msg.includes('unavailable');

      if ((isQuotaError || isServerError) && attempt < maxRetries) {
        attempt++;

        // Strategy: 
        // 429 often requires a "cooling off" period. We start high (4s).
        // 503 is often transient. We start lower (2s).
        // Sequence for Quota: ~4s, ~8s, ~16s, ~32s, ~64s
        let baseDelay = isQuotaError ? 4000 : 2000;

        // Add significant jitter to prevent synchronized retries across clients
        const jitter = Math.random() * 2000;
        const delay = (baseDelay * Math.pow(2, attempt - 1)) + jitter;

        console.warn(`[${operationName}] ${isQuotaError ? 'Quota Exceeded' : 'Server Busy'}. Waiting ${Math.round(delay/1000)}s... (Try ${attempt}/${maxRetries})`);

        await wait(delay);
        continue;
      }

      // Final Error Handling after retries exhausted
      if (isQuotaError) {
        console.error(`[${operationName}] FAILED: Quota limit hit after ${maxRetries} attempts.`);
        throw new Error(`⚠️ Server-Limit (429). Die KI-Systeme sind momentan ausgelastet. Wir haben es ${maxRetries}-mal versucht. Bitte warten Sie 1 Minute.`);
      }

      if (isServerError) {
         console.error(`[${operationName}] FAILED: Server unavailable after ${maxRetries} attempts.`);
         throw new Error("⚠️ Server nicht erreichbar (503). Bitte versuchen Sie es in Kürze erneut.");
      }

      console.error(`[${operationName}] Critical Failure:`, error);
      throw error;
    }
  }
}

