// --- Custom Control Knob Component (Fixed for Touch/Desktop & Resizable) ---
const ControlKnob: React.FC<{ value: number; onChange: (val: number) => void; label?: string; color?: string; size?: number }> = ({ value, onChange, label, color = "white", size = 48 }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startYRef = useRef<number>(0);
  const startValueRef = useRef<number>(0);

  const handlePointerDown = (e: React.PointerEvent) => {
    e.preventDefault();
    e.stopPropagation(); // Stop propagation to prevent scrolling in parent containers
    setIsDragging(true);
    startYRef.current = e.clientY;
    startValueRef.current = value;
    (e.target as Element).setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDragging) return;
    e.preventDefault();
    const deltaY = startYRef.current - e.clientY;
    const change = deltaY / 150; 
    let newValue = startValueRef.current + change;
    newValue = Math.max(0, Math.min(1, newValue));
    onChange(newValue);
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    setIsDragging(false);
    (e.target as Element).releasePointerCapture(e.pointerId);
  };

  // Generate ticks
  const ticks = [];
  const numTicks = 20; 
  const startAngle = 135;
  const endAngle = 405;

  for (let i = 0; i < numTicks; i++) {
    const pct = i / (numTicks - 1);
    const angle = startAngle + (endAngle - startAngle) * pct;
    const rad = (angle * Math.PI) / 180;
    const isLit = value >= pct;

    const innerR = 32;
    const outerR = 42;
    const x1 = 50 + innerR * Math.cos(rad);
    const y1 = 50 + innerR * Math.sin(rad);
    const x2 = 50 + outerR * Math.cos(rad);
    const y2 = 50 + outerR * Math.sin(rad);

    ticks.push(
      <line 
        key={i}
        x1={x1} y1={y1} x2={x2} y2={y2}
        stroke={isLit ? color : "#334155"}
        strokeWidth={2}
        strokeLinecap="round"
        className={`transition-colors duration-100 ${isLit ? 'opacity-100' : 'opacity-30'}`}
      />
    );
  }

  const knobAngle = startAngle + (endAngle - startAngle) * value;
  const knobRad = (knobAngle * Math.PI) / 180;
  const dotR = 18;
  const dotX = 50 + dotR * Math.cos(knobRad);
  const dotY = 50 + dotR * Math.sin(knobRad);

  return (
    <div 
      className="relative flex flex-col items-center justify-center cursor-ns-resize group select-none touch-none"
      style={{ width: size, height: size }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerLeave={handlePointerUp}
      title={label}
    >
      <svg width="100%" height="100%" viewBox="0 0 100 100" className="pointer-events-none">
        {ticks}
        <circle cx="50" cy="50" r="26" fill="black" opacity="0.5" filter="blur(2px)" />
        <circle 
          cx="50" cy="50" r="25" 
          fill="url(#knobGradient)" 
          stroke="#1e293b" 
          strokeWidth="1"
          className="drop-shadow-lg"
        />
        <defs>
          <linearGradient id="knobGradient" x1="0%" y1="0%" x2="0%" y2="100%">
            <stop offset="0%" stopColor="#334155" />
            <stop offset="100%" stopColor="#0f172a" />
          </linearGradient>
        </defs>
        <circle 
          cx={dotX} cy={dotY} r="3" 
          fill={value > 0 ? color : "#64748b"} 
          className={value > 0 ? "drop-shadow-[0_0_4px_rgba(255,255,255,0.8)]" : ""}
        />
      </svg>
      {label && (
          <div 
            className="absolute -bottom-3 font-mono font-bold text-slate-500 uppercase tracking-wider pointer-events-none whitespace-nowrap"
            style={{ fontSize: Math.max(8, size * 0.22) + 'px' }}
          >
            {label}
          </div>
      )}
    </div>
  );
};


