                    </div>

                    {/* Cloud/Share Button */}
                    <button onClick={handleShare} disabled={isRendering} className="flex-1 rounded-2xl border border-sky-500/30 bg-sky-500/10 text-sky-400 hover:bg-sky-500 hover:text-white transition-all flex flex-col items-center justify-center gap-2 group disabled:opacity-50" title="Save to Drive / Share">
