      {/* --- VISION & MANUSCRIPT TERMINAL --- */}
      <section className="relative">
        <div className="absolute inset-0 bg-indigo-500/5 blur-[120px] rounded-full"></div>

        {/* TOOLBAR */}
        <div className={`transition-all duration-500 ease-in-out overflow-hidden ${showControls ? 'max-h-52 opacity-100 mb-4' : 'max-h-0 opacity-0 mb-0'}`}>
          <div className="bg-[#0f1115]/95 border border-white/10 rounded-xl p-2 shadow-2xl relative z-20 backdrop-blur-xl">

             {/* Main Flex Container */}
             <div className="flex flex-col sm:flex-row items-center justify-between gap-4">

                 {/* Left: Input Actions */}
                 <div className="flex items-center gap-2 w-full sm:w-auto justify-center sm:justify-start">
                    {/* Dictation Button */}
                    <button 
                        onClick={startDictation} 
                        className={`
                            h-10 px-4 rounded-lg flex items-center justify-center gap-2 transition-all duration-300 relative
                            ${isDictating 
                                ? 'bg-red-500/20 text-red-400 border border-red-500/30 w-full sm:w-auto' 
                                : 'bg-white/5 hover:bg-white/10 text-slate-400 hover:text-white border border-transparent'}
                        `}
                        title="Spracheingabe"
                    >
                        {isDictating && <span className="absolute top-2 right-2 w-1.5 h-1.5 bg-red-500 rounded-full animate-pulse"></span>}
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                        <span className="text-xs font-bold uppercase hidden sm:inline">{isDictating ? 'Stop' : 'Rec'}</span>
                    </button>

                    {/* Vision Scanner Button */}
                    <button 
                        onClick={() => setShowScanner(true)} 
                        className="h-10 w-10 sm:w-auto sm:px-4 rounded-lg flex items-center justify-center gap-2 bg-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all border border-transparent hover:border-white/5"
                        title="Vision Scan"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                        <span className="text-xs font-bold uppercase hidden sm:inline">Scan</span>
                    </button>

                    {/* Translate Button */}
                    <button 
                        onClick={handleTranslate}
                        disabled={isTranslating}
                        className={`
                            h-10 w-10 sm:w-auto sm:px-4 rounded-lg flex items-center justify-center gap-2 transition-all duration-300 relative
                            ${arabicText 
                                ? 'bg-amber-500/20 text-amber-400 border border-amber-500/30' 
                                : 'bg-white/5 hover:bg-white/10 text-slate-400 hover:text-white border border-transparent'}
                        `}
                        title="Translate to Arabic"
                    >
                        <svg className={`w-5 h-5 ${isTranslating ? 'animate-spin' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            {isTranslating ? (
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                            ) : (
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 5h12M9 3v2m1.048 9.5A18.022 18.022 0 016.412 9m6.088 9h7M11 21l5-10 5 10M12.751 5C11.783 10.77 8.07 15.61 3 18.129" />
                            )}
                        </svg>
                        <span className="text-xs font-bold uppercase hidden sm:inline">Translate</span>
                    </button>
                 </div>

                 {/* Center: Voice Selector */}
                 <div className="w-full sm:flex-1 sm:max-w-md px-1">
                    <div className="relative group">
                       <select 
                          value={selectedVoice.id}
                          onChange={(e) => {
                             const v = GERMAN_VOICES.find(v => v.id === e.target.value);
                             if(v) setSelectedVoice(v);
                          }}
                          className="w-full appearance-none bg-black/40 border border-white/10 rounded-lg text-sm font-bold text-slate-200 py-3 px-4 focus:outline-none focus:border-indigo-500/50 hover:bg-white/5 transition-colors cursor-pointer truncate pr-10 shadow-inner"
                       >
                          {GERMAN_VOICES.map(v => (
                              <option key={v.id} value={v.id} className="bg-[#0f1115] text-slate-300">
                                 {v.name} • {v.persona}
                              </option>
                          ))}
                       </select>
                       <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-indigo-400">
                          <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                       </div>
                    </div>
                 </div>

                 {/* Right: Audio FX Knobs */}
                 <div className="flex items-center gap-4 w-full sm:w-auto justify-center sm:justify-end py-1">
                     {/* Loop Toggle */}
                     <button 
                        onClick={() => setIsLoopEnabled(!isLoopEnabled)}
                        className={`
                            w-10 h-10 rounded-lg flex items-center justify-center transition-all duration-300 flex-shrink-0
                            ${isLoopEnabled 
                                ? 'bg-indigo-500/20 text-indigo-300 border border-indigo-500/30' 
                                : 'bg-white/5 hover:bg-white/10 text-slate-400 hover:text-white border border-transparent'}
                        `}
                        title="Toggle Loop Mode"
                    >
                        <svg className={`w-5 h-5 transition-transform duration-500 ${isLoopEnabled ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                        </svg>
                    </button>

                    <div className="w-px h-8 bg-white/10 mx-1 hidden sm:block"></div>

                    {/* Effect Knobs */}
                    <div className="flex items-center gap-2">
                        <ControlKnob 
                            value={speedKnobValue} 
                            onChange={setSpeedKnobValue} 
                            label="SPD" 
                            color="#a5b4fc" 
                            size={36} 
                            formatValue={(v) => (0.5 + v * 2).toFixed(1) + 'x'}
                        />
                        <ControlKnob 
                            value={reverbLevel} 
                            onChange={setReverbLevel} 
                            label="REV" 
                            color="#f472b6" 
                            size={36} 
                        />
                        <ControlKnob 
                            value={delayLevel} 
                            onChange={setDelayLevel} 
                            label="DLY" 
                            color="#22d3ee" 
                            size={36} 
                        />
                        <div className="ml-1">
                           <ControlKnob 
                                value={volume} 
                                onChange={setVolume} 
                                label="VOL" 
                                color="#ffffff" 
                                size={42} 
                            />
                        </div>
                    </div>
                 </div>
             </div>
          </div>
        </div>

        {/* Terminal Body */}
        <div className="relative group rounded-2xl overflow-hidden border border-white/10 bg-[#0a0c12]/80 backdrop-blur-xl shadow-2xl transition-all duration-500 hover:border-indigo-500/30">
          <div className="absolute top-0 left-0 w-full h-0.5 bg-gradient-to-r from-transparent via-indigo-500 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-700"></div>

          <div className="relative min-h-[320px] p-6 font-mono text-lg leading-relaxed">
            {/* Toggle Controls Button (Hidden functionality revealer) */}
            <button 
                onClick={() => setShowControls(!showControls)}
                className="absolute top-3 right-3 z-30 p-2 text-slate-700 hover:text-indigo-400 transition-colors opacity-50 hover:opacity-100"
                title={showControls ? "Hide Toolbar" : "Show Toolbar"}
            >
                {showControls ? (
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" />
                  </svg>
                ) : (
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                  </svg>
                )}
            </button>
            {/* ... rest of the component ... */}
            {/* Visualizer Canvas Overlay */}
            <canvas 
              ref={visualizerCanvasRef} 
              width={800} 
              height={100} 
              className={`absolute bottom-0 left-0 w-full h-32 pointer-events-none transition-opacity duration-500 z-0 ${isPlaying ? 'opacity-30' : 'opacity-0'}`}
            />

            {/* Playback Text Overlay */}
            {isPlaying && (
              <div 
                ref={overlayRef}
                className="absolute inset-0 z-20 bg-[#05070a]/90 backdrop-blur-sm p-6 overflow-y-auto pointer-events-none scroll-smooth scrollbar-thin scrollbar-thumb-indigo-500/30 scrollbar-track-transparent"
              >
                <div className="flex flex-wrap gap-x-1.5 gap-y-1">
                  {(() => {
                    let wordCounter = 0;
                    return words.map((part, idx) => {
                      const isWhitespace = /^\s+$/.test(part);
                      const isActive = !isWhitespace && wordCounter === currentWordIndex;
                      const localIndex = wordCounter;

                      if (!isWhitespace) wordCounter++;

                      return (
                        <span 
                          key={`w-${idx}`} 
                          ref={(el) => {
                             if (!isWhitespace && el) {
                               wordRefs.current[localIndex] = el;
                             }
                          }}
                          className={`transition-all duration-150 relative inline-block ${isActive ? 'text-transparent bg-clip-text bg-gradient-to-r from-white to-indigo-200 font-bold scale-105 z-10 drop-shadow-[0_0_10px_rgba(99,102,241,0.8)]' : 'text-slate-600'}`}
                        >
                          {part}
                        </span>
                      );
                    });
                  })()}
                </div>
              </div>
            )}

            <textarea
              className={`w-full h-full min-h-[300px] bg-transparent border-none outline-none resize-none text-slate-300 placeholder-slate-700/50 selection:bg-indigo-500/30 relative z-10 ${isPlaying ? 'opacity-0' : 'opacity-100'}`}
              placeholder="// Geben Sie Ihren Text ein oder initialisieren Sie den Scan-Vorgang..."
              value={text}
              onChange={(e) => setText(e.target.value)}
              disabled={isPlaying}
              spellCheck={false}
            />
          </div>

          {/* Terminal Status Bar */}
          <div className="bg-[#050608] border-t border-white/5 px-4 py-3 flex justify-between items-center text-[10px] font-mono text-slate-500 uppercase tracking-widest relative z-30">
             <div className="flex items-center gap-4">
                 <div className="flex items-center gap-2">
                    <span className="w-1.5 h-1.5 rounded-full bg-slate-700"></span>
                    <span>Chars: {text.length}</span>
                 </div>
                 {text.length > 0 && <span className="text-slate-700">|</span>}
                 {text.length > 0 && <span>~{(text.length / 15).toFixed(0)} Sec Est.</span>}
             </div>

             <div className="flex items-center gap-3">
               <span className={isDictating ? "text-red-400 animate-pulse font-bold" : ""}>{isDictating ? "● RECORDING" : "MIC STANDBY"}</span>
               <span className="w-px h-3 bg-white/10"></span>
               <span className={isPlaying ? "text-indigo-400 animate-pulse font-bold" : ""}>{isPlaying ? "PLAYBACK ACTIVE" : "SYSTEM IDLE"}</span>
             </div>
          </div>
        </div>

        {/* Translation Output Module */}
        {arabicText && (
          <div className="mt-4 relative animate-fadeInUp">
            <div className="bg-[#080a0f] border border-white/5 rounded-2xl p-6 relative overflow-hidden group/trans hover:border-amber-500/30 transition-colors duration-500">
              <div className="flex justify-between items-start mb-4">
                <span className="text-[10px] text-amber-500/80 font-mono tracking-widest uppercase flex items-center gap-2">
                    <span className="w-1.5 h-1.5 bg-amber-500 rounded-full"></span>
                    Translation_Output [Arabic]
