import { GoogleGenAI } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Helper to execute API calls with exponential backoff for 429/503/XHR/Internal errors.
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 3, operationName = "API Call"): Promise<T> {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (error: any) {
      // Normalize error message
      const msg = (error.message || error.toString()).toLowerCase();
      const status = error.status || error.code || 0;

      // Detect Quota/Rate Limit Errors
      const isQuotaError = 
        msg.includes('429') || 
        status === 429 || 
        msg.includes('resource has been exhausted') || 
        msg.includes('too many requests') ||
        msg.includes('quota');

      // Detect Server Overload/Availability/Internal Errors
      const isServerError = 
        status === 503 || 
        status === 500 ||
        msg.includes('503') || 
        msg.includes('500') ||
        msg.includes('overloaded') ||
        msg.includes('unavailable') ||
        msg.includes('internal error') ||
        msg.includes('internal');

      // Detect XHR/RPC Network Errors (code 6, xhr error)
      const isNetworkError = 
        msg.includes('rpc failed') || 
        msg.includes('xhr error') || 
        msg.includes('error code: 6') ||
        msg.includes('fetch failed');

      if ((isQuotaError || isServerError || isNetworkError) && attempt < maxRetries) {
        attempt++;

        let baseDelay = isQuotaError ? 4000 : 2000;
        const jitter = Math.random() * 2000;
        const delay = (baseDelay * Math.pow(2, attempt - 1)) + jitter;

        console.warn(`[${operationName}] Retryable Error (${status} - ${isNetworkError ? 'Network' : 'Server'}). Waiting ${Math.round(delay/1000)}s... (Try ${attempt}/${maxRetries})`);

        await wait(delay);
        continue;
      }

      // Final Error Handling after retries exhausted
      if (isQuotaError) {
        throw new Error(`⚠️ Server-Limit (429). Die KI-Systeme sind momentan ausgelastet. Bitte warten Sie einen Moment.`);
      }

      if (isServerError) {
         throw new Error(`⚠️ Server-Fehler (${status}). Die KI hat ein internes Problem gemeldet. Bitte kürzen Sie den Text oder versuchen Sie es erneut.`);
      }

      if (isNetworkError) {
         throw new Error("⚠️ Verbindungsfehler. Bitte überprüfen Sie Ihre Internetverbindung.");
      }

      console.error(`[${operationName}] Critical Failure:`, error);
      throw error;
    }
  }
}

/**
 * Generates high-quality German speech from text.
 */
export const generateSpeech = async (text: string, voiceName: string, cloningPersona?: string) => {
  return withRetry(async () => {
    const ai = getAI();

    // CLEANUP: Clean text strictly for TTS to avoid weird characters breaking the model
    const cleanText = text.trim();
    if (!cleanText) throw new Error("Text darf nicht leer sein.");

    // Build configuration
    // Note: Removed systemInstruction as it causes 500 Internal Errors with gemini-2.5-flash-preview-tts
    const config: any = {
      responseModalities: ['AUDIO'], 
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    };

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: cleanText }] }],
      config: config,
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
       // Check if we got text back instead (error description)
       const textResponse = response.candidates?.[0]?.content?.parts?.[0]?.text;
       if (textResponse) {
          console.warn("TTS Model returned text:", textResponse);
          throw new Error("Das Modell hat die Audio-Generierung abgelehnt. Möglicherweise verstößt der Text gegen Richtlinien.");
       }
       throw new Error("Keine Audiodaten empfangen. Bitte versuchen Sie es erneut.");
    }

    return base64Audio;
  }, 3, "TTS Generation");
};

