         </button>

         <div className="flex-[2] flex gap-4">
            {isPlaying ? (
              <button onClick={() => stopAllAudio(true)} className="flex-1 rounded-2xl border border-red-500/30 bg-red-500/10 text-red-400 hover:bg-red-500 hover:text-white transition-all flex flex-col items-center justify-center gap-3 animate-pulse hover:animate-none group">
                <div className="w-5 h-5 rounded bg-current shadow-[0_0_15px_rgba(248,113,113,0.5)] group-hover:shadow-none transition-all"></div>
                <span className="text-[9px] font-black uppercase tracking-widest">Stop</span>
              </button>
            ) : (
                lastAudioBase64 ? (
                <div className="flex-1 flex gap-2">
                    <div className="relative flex-1 group">
                         <select value={downloadQuality} onChange={(e) => setDownloadQuality(Number(e.target.value))} className="w-full h-full appearance-none bg-[#0a0c10] border border-white/10 rounded-2xl text-[9px] font-bold text-slate-400 uppercase tracking-widest px-4 text-center focus:outline-none focus:border-indigo-500/50 hover:bg-white/5 transition-all cursor-pointer">
                            <option value={24000}>320 KBPS (Studio)</option>
                            <option value={16000}>256 KBPS (Medium)</option>
                         </select>
                         <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-600"><svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg></div>
                    </div>
                    <button onClick={handleDownload} disabled={isRendering} className="flex-1 rounded-2xl border border-emerald-500/30 bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500 hover:text-white transition-all flex flex-col items-center justify-center gap-2 group disabled:opacity-50">
                        {isRendering ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <svg className="w-5 h-5 group-hover:-translate-y-0.5 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>}
                        <span className="text-[9px] font-black uppercase tracking-widest">Save</span>
                    </button>
                </div>
                ) : (
                  <div className="flex-1 rounded-2xl border border-white/5 bg-white/5 flex flex-col items-center justify-center gap-3 opacity-30 cursor-not-allowed">
                      <div className="w-5 h-5 rounded bg-slate-600"></div>
                      <span className="text-[9px] font-black uppercase tracking-widest text-slate-600">Ready</span>
                  </div>
                )
            )}
         </div>
      </section>
    </div>
  );
};

import { GoogleGenAI, Modality } from "@google/genai";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Helper to execute API calls with exponential backoff for 429/503/XHR/Internal errors.
 */
async function withRetry<T>(fn: () => Promise<T>, maxRetries = 3, operationName = "API Call"): Promise<T> {
  let attempt = 0;
  while (true) {
    try {
      return await fn();
    } catch (error: any) {
      // Normalize error message
      const msg = (error.message || error.toString()).toLowerCase();
      const status = error.status || error.code || 0;

      // Detect Quota/Rate Limit Errors
      const isQuotaError = 
        msg.includes('429') || 
        status === 429 || 
        msg.includes('resource has been exhausted') || 
        msg.includes('too many requests') || 
        msg.includes('quota');

      // Detect Server Overload/Availability/Internal Errors
      const isServerError = 
        status === 503 || 
        status === 500 ||
        msg.includes('503') || 
        msg.includes('500') ||
        msg.includes('overloaded') ||
        msg.includes('unavailable') ||
        msg.includes('internal error') ||
        msg.includes('internal');

      // Detect XHR/RPC Network Errors (code 6, xhr error)
      const isNetworkError = 
        msg.includes('rpc failed') || 
        msg.includes('xhr error') || 
        msg.includes('error code: 6') ||
        msg.includes('fetch failed') ||
        msg.includes('networkerror');

      if ((isQuotaError || isServerError || isNetworkError) && attempt < maxRetries) {
        attempt++;

        let baseDelay = isQuotaError ? 4000 : 2000;
        const jitter = Math.random() * 2000;
        const delay = (baseDelay * Math.pow(2, attempt - 1)) + jitter;

        console.warn(`[${operationName}] Retryable Error (${status}). Waiting ${Math.round(delay/1000)}s... (Try ${attempt}/${maxRetries})`);

        await wait(delay);
        continue;
      }

      // Final Error Handling
      if (isQuotaError) throw new Error("⚠️ Server ausgelastet (429). Bitte warten Sie kurz.");
      if (isServerError) throw new Error("⚠️ Interner KI-Fehler (500). Bitte kürzen Sie den Text.");
      if (isNetworkError) throw new Error("⚠️ Netzwerkfehler. Bitte Internet prüfen.");

      console.error(`[${operationName}] Critical Failure:`, error);
      throw error;
    }
  }
}

/**
 * Generates high-quality German speech.
 * Includes explicit error handling for missing audio data.
 */
export const generateSpeech = async (text: string, voiceName: string, cloningPersona?: string) => {
  return withRetry(async () => {
    const ai = getAI();

    const cleanText = text.trim();
    if (!cleanText) throw new Error("Text darf nicht leer sein.");

    // Inject persona into text for style guidance, but keep it minimal to avoid confusion.
    // If specific persona is requested, use it, otherwise default to clean.
    const promptText = cloningPersona 
      ? `(Style: ${cloningPersona}) ${cleanText}`
      : cleanText;

    // Strict configuration for Gemini 2.5 TTS
    const config: any = {
      responseModalities: [Modality.AUDIO], 
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    };

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: promptText }] }],
      config: config,
    });

    const candidate = response.candidates?.[0];
    if (!candidate) throw new Error("Keine Antwort vom Server erhalten.");

    // Check for Safety or Recitation blocks
    if (candidate.finishReason && candidate.finishReason !== 'STOP') {
        if (candidate.finishReason === 'SAFETY') throw new Error("Generierung blockiert (Sicherheitsrichtlinien).");
        if (candidate.finishReason === 'RECITATION') throw new Error("Generierung blockiert (Urheberrecht/Wiederholung).");
        if (candidate.finishReason === 'OTHER') console.warn("TTS Finish Reason: OTHER (Proceeding check)");
    }

    const part = candidate.content?.parts?.[0];
    if (!part) throw new Error("Leere Antwort (Keine Inhaltsteile).");

    // 1. Check for Audio
    const base64Audio = part.inlineData?.data;
    if (base64Audio) return base64Audio;

    // 2. Check for Text Refusal (Model refused to generate audio and sent text instead)
    const textResponse = part.text;
    if (textResponse) {
       console.warn("TTS Refusal:", textResponse);
       // Return specific error if model refuses
       throw new Error(`KI-Verweigerung: "${textResponse.substring(0, 100)}..."`);
    }

    throw new Error("Keine Audiodaten empfangen. Bitte versuchen Sie es erneut.");
  }, 3, "TTS Generation");
};

/**
 * Extracts text from an image.
 */
export const extractTextFromImage = async (base64Image: string) => {
  return withRetry(async () => {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          { inlineData: { mimeType: "image/jpeg", data: base64Image } },
          { text: "OCR: Extrahiere den gesamten Text exakt auf Deutsch." },
        ],
      },
    });
    return response.text || "";
  }, 3, "Vision Extraction");
};

/**
 * Translates text from German to Arabic.
 */
export const translateText = async (text: string): Promise<string> => {
  return withRetry(async () => {
    const ai = getAI();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [{ parts: [{ text: `Translate German to Arabic. Output only the Arabic translation.\n\n${text}` }] }],
    });
    return response.text?.trim() || "";
  }, 3, "Translation");
};

